ALL_PYQS_CACHE = [{'id': 'PYQ-2024-EM-01', 'year': 2024, 'subject': 'Engineering Mathematics', 'topic': 'Linear Algebra', 'type': 'NAT', 'marks': 2, 'text': 'Let A be a 3 x 3 matrix with real entries. The eigenvalues of A are 1, 2, and 3. The determinant of the matrix (A^2 + 2A + I) is _________.', 'answer': '576', 'explanation': 'If λ is an eigenvalue of A, the eigenvalues of f(A) = A^2 + 2A + I are f(λ) = (λ + 1)^2.\nFor λ1 = 1: (1 + 1)^2 = 4.\nFor λ2 = 2: (2 + 1)^2 = 9.\nFor λ3 = 3: (3 + 1)^2 = 16.\nThe determinant of a matrix equals the product of its eigenvalues:\nDet(f(A)) = 4 * 9 * 16 = 576.', 'source_url': 'https://gate2024.iisc.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2024-EM-02', 'year': 2024, 'subject': 'Engineering Mathematics', 'topic': 'Discrete Mathematics', 'type': 'MCQ', 'marks': 1, 'text': 'Let G = (V, E) be a simple connected planar graph with 20 vertices and each face bounded by at least 3 edges. What is the MAXIMUM number of edges possible in G?', 'options': {'A': '54', 'B': '60', 'C': '36', 'D': '48'}, 'answer': 'A', 'explanation': "In any connected planar graph with V >= 3 and face degree >= 3:\n2E >= 3R => R <= 2E / 3.\nSubstituting into Euler's formula V - E + R = 2:\nV - E + 2E / 3 >= 2 => V - E/3 >= 2 => E <= 3V - 6.\nFor V = 20: E <= 3(20) - 6 = 60 - 6 = 54.", 'source_url': 'https://gate2024.iisc.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2023-EM-01', 'year': 2023, 'subject': 'Engineering Mathematics', 'topic': 'Probability & Statistics', 'type': 'NAT', 'marks': 2, 'text': 'A fair coin is tossed independently until a head appears for the first time. The probability that the number of required tosses is an ODD integer is _________ (rounded off to two decimal places).', 'answer': '0.67', 'explanation': 'P(X = k) = (1/2)^k.\nP(X is odd) = P(X = 1) + P(X = 3) + P(X = 5) + ...\n= (1/2) / [1 - (1/4)] = (1/2) / (3/4) = 2/3 ≈ 0.67.', 'source_url': 'https://gate2023.iitk.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2023-EM-02', 'year': 2023, 'subject': 'Engineering Mathematics', 'topic': 'Calculus', 'type': 'NAT', 'marks': 1, 'text': 'Evaluate the limit: lim (x -> 0) [sin(5x) - 5x] / x^3. The value is _________ (rounded to one decimal place).', 'answer': '-20.8', 'explanation': 'Using Taylor expansion: sin(5x) = 5x - (5x)^3 / 6 + O(x^5) = 5x - 125x^3 / 6.\n[sin(5x) - 5x] / x^3 = -125 / 6 ≈ -20.83.', 'source_url': 'https://gate2023.iitk.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2022-EM-01', 'year': 2022, 'subject': 'Engineering Mathematics', 'topic': 'Discrete Mathematics', 'type': 'MSQ', 'marks': 2, 'text': 'Which of the following statements is/are TRUE for any simple graph G with n vertices and m edges?', 'options': {'A': 'If G is a tree, then m = n - 1', 'B': 'If G is bipartite, G contains no odd cycles', 'C': 'The sum of degrees of all vertices is always 2m', 'D': 'Every planar graph can be vertex colored with at most 3 colors'}, 'answer': 'A, B, C', 'explanation': 'A, B, and C are fundamental graph theory theorems. D is False because planar graphs require up to 4 colors (Four Color Theorem, e.g. K4).', 'source_url': 'https://gate2022.iitkgp.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2021-EM-01', 'year': 2021, 'subject': 'Engineering Mathematics', 'topic': 'Linear Algebra', 'type': 'MCQ', 'marks': 1, 'text': 'Let A be an n x n non-singular matrix. If λ is an eigenvalue of A, then which of the following is an eigenvalue of adj(A)?', 'options': {'A': 'det(A) / λ', 'B': 'λ / det(A)', 'C': 'λ * det(A)', 'D': 'det(A) - λ'}, 'answer': 'A', 'explanation': 'adj(A) = det(A) * A^(-1). Eigenvalue of A^(-1) is 1/λ. Hence eigenvalue of adj(A) is det(A) * (1/λ) = det(A) / λ.', 'source_url': 'https://gate2021.iitb.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2020-EM-01', 'year': 2020, 'subject': 'Engineering Mathematics', 'topic': 'Combinatorics', 'type': 'NAT', 'marks': 2, 'text': "The number of permutations of the letters in the word 'PROBABILITY' is _________.", 'answer': '9979200', 'explanation': 'Word has 11 letters: P:1, R:1, O:1, B:2, A:1, I:2, L:1, T:1, Y:1.\nTotal permutations = 11! / (2! * 2!) = 39916800 / 4 = 9,979,200.', 'source_url': 'https://gate2020.iitd.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2019-EM-01', 'year': 2019, 'subject': 'Engineering Mathematics', 'topic': 'Linear Algebra', 'type': 'NAT', 'marks': 2, 'text': 'Consider the system of equations:\nx + y + z = 6\nx + 2y + 3z = 10\nx + 2y + λz = μ\nThe value of λ for which the system has INFINITELY MANY solutions is _________.', 'answer': '3', 'explanation': 'Row reduction of augmented matrix [A|B]:\nR2 -> R2 - R1: [0, 1, 2 | 4]\nR3 -> R3 - R2: [0, 0, λ - 3 | μ - 10]\nFor infinitely many solutions, rank(A) = rank([A|B]) < 3.\nThis requires λ - 3 = 0 => λ = 3 (and μ = 10).', 'source_url': 'https://gate2019.iitm.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2018-EM-01', 'year': 2018, 'subject': 'Engineering Mathematics', 'topic': 'Calculus', 'type': 'NAT', 'marks': 1, 'text': 'The value of ∫ [x * e^x] dx from x = 0 to x = 1 is _________ (rounded off to two decimal places).', 'answer': '1.00', 'explanation': "Integration by parts: ∫ u v' = u v - ∫ u' v.\nLet u = x, v' = e^x => u' = 1, v = e^x.\n∫ x e^x dx = x e^x - e^x = e^x (x - 1).\nEvaluated from 0 to 1:\n[e^1 (1 - 1)] - [e^0 (0 - 1)] = 0 - (-1) = 1.00.", 'source_url': 'https://gate2018.iitg.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2017-EM-01', 'year': 2017, 'subject': 'Engineering Mathematics', 'topic': 'Discrete Mathematics', 'type': 'MCQ', 'marks': 2, 'text': 'Let P and Q be two propositions. The proposition ~(P <-> Q) is logically equivalent to which of the following?', 'options': {'A': 'P ⊕ Q (XOR)', 'B': 'P <-> ~Q', 'C': '~P <-> Q', 'D': 'All of the above'}, 'answer': 'D', 'explanation': 'P <-> Q is True when P and Q have identical truth values. ~(P <-> Q) is True when P and Q have OPPOSITE truth values, which is the exact definition of XOR (P ⊕ Q). Also (P <-> ~Q) and (~P <-> Q) are both identical to P ⊕ Q. Hence, all options are equivalent.', 'source_url': 'https://gate2017.iitr.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2024-DL-01', 'year': 2024, 'subject': 'Digital Logic', 'topic': 'Boolean Algebra', 'type': 'MCQ', 'marks': 1, 'text': 'The minimal sum-of-products (SOP) expression for the Boolean function F(A, B, C) = ∑ m(1, 3, 4, 5, 7) is:', 'options': {'A': "C + A B'", 'B': "C + A' B", 'C': "A' C + A B'", 'D': "B C + A' B'"}, 'answer': 'A', 'explanation': "Minterms m(1,3,5,7) group into a 4-cell quad yielding C. Minterms m(4,5) group into a 2-cell pair yielding A B'. Result: C + A B'.", 'source_url': 'https://gate2024.iisc.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2023-DL-01', 'year': 2023, 'subject': 'Digital Logic', 'topic': 'Sequential Circuits', 'type': 'NAT', 'marks': 2, 'text': 'A 4-bit Johnson counter is initialized to state 0000. How many distinct states does it cycle through before returning to 0000?', 'answer': '8', 'explanation': 'An n-bit Johnson counter cycles through 2n distinct states. For n = 4: 2 * 4 = 8 states.', 'source_url': 'https://gate2023.iitk.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2022-DL-01', 'year': 2022, 'subject': 'Digital Logic', 'topic': 'Combinational Circuits', 'type': 'MCQ', 'marks': 2, 'text': "A 2-to-1 multiplexer has select line S0 and inputs I0, I1. If S0 = A, I0 = B, and I1 = B', the function implemented is:", 'options': {'A': 'A ⊕ B', 'B': 'A ⊙ B', 'C': 'A + B', 'D': 'A * B'}, 'answer': 'A', 'explanation': "Y = S0' * I0 + S0 * I1 = A' B + A B' = A ⊕ B.", 'source_url': 'https://gate2022.iitkgp.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2021-DL-01', 'year': 2021, 'subject': 'Digital Logic', 'topic': 'Number Representation', 'type': 'NAT', 'marks': 1, 'text': "What is the decimal equivalent of the 8-bit signed 2's complement binary number 11110101?", 'answer': '-11', 'explanation': 'MSB is 1 (negative). Value = -2^7 + (1*2^6 + 1*2^5 + 1*2^4 + 0*2^3 + 1*2^2 + 0*2^1 + 1*2^0) = -128 + (64 + 32 + 16 + 4 + 1) = -128 + 117 = -11.', 'source_url': 'https://gate2021.iitb.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2020-DL-01', 'year': 2020, 'subject': 'Digital Logic', 'topic': 'Sequential Circuits', 'type': 'NAT', 'marks': 2, 'text': 'How many flip-flops are minimally required to construct a mod-60 synchronous counter?', 'answer': '6', 'explanation': 'An n flip-flop counter can have at most 2^n states. We need 2^n >= 60. 2^5 = 32 < 60; 2^6 = 64 >= 60. Hence n = 6 flip-flops.', 'source_url': 'https://gate2020.iitd.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2019-DL-01', 'year': 2019, 'subject': 'Digital Logic', 'topic': 'Logic Gates', 'type': 'MCQ', 'marks': 1, 'text': 'The minimum number of 2-input NAND gates required to implement a 2-input XOR gate is:', 'options': {'A': '4', 'B': '5', 'C': '3', 'D': '6'}, 'answer': 'A', 'explanation': 'Standard universal logic realization: 2-input XOR requires exactly 4 NAND gates.', 'source_url': 'https://gate2019.iitm.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2018-DL-01', 'year': 2018, 'subject': 'Digital Logic', 'topic': 'Karnaugh Maps', 'type': 'NAT', 'marks': 2, 'text': 'Consider the function F(w, x, y, z) = ∑ m(0, 2, 5, 7, 8, 10, 13, 15). The number of essential prime implicants is _________.', 'answer': '2', 'explanation': "Minterms (0, 2, 8, 10) form a corner quad: x' z'. Minterms (5, 7, 13, 15) form an inner quad: x z. Both quads cover unique minterms and are essential. Total = 2.", 'source_url': 'https://gate2018.iitg.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2017-DL-01', 'year': 2017, 'subject': 'Digital Logic', 'topic': 'Flip-Flops', 'type': 'MCQ', 'marks': 2, 'text': 'A T flip-flop is constructed from a JK flip-flop by connecting J and K together to input T. What is the characteristic equation Q_next?', 'options': {'A': 'T ⊕ Q', 'B': 'T * Q', 'C': 'T + Q', 'D': "T' * Q'"}, 'answer': 'A', 'explanation': "JK characteristic equation: Q_next = J Q' + K' Q. Substituting J = K = T gives Q_next = T Q' + T' Q = T ⊕ Q.", 'source_url': 'https://gate2017.iitr.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2016-DL-01', 'year': 2016, 'subject': 'Digital Logic', 'topic': 'Combinational Circuits', 'type': 'NAT', 'marks': 2, 'text': 'How many 3-to-8 line decoders with enable inputs are needed to construct a 4-to-16 line decoder without any other logic gates?', 'answer': '2', 'explanation': 'Use two 3-to-8 decoders. Connect lower 3 bits (A2, A1, A0) to both decoders. Connect the MSB (A3) directly to enable of decoder 2 and inverted (via active low enable) to decoder 1. Exactly 2 decoders are needed.', 'source_url': 'https://gate2016.iisc.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2015-DL-01', 'year': 2015, 'subject': 'Digital Logic', 'topic': 'Number Representation', 'type': 'NAT', 'marks': 1, 'text': "The range of integers that can be represented using 8-bit 2's complement representation is from -128 to _________.", 'answer': '127', 'explanation': "For n-bit 2's complement, range is -2^(n-1) to +2^(n-1) - 1. For n = 8: -2^7 to +2^7 - 1 = -128 to +127.", 'source_url': 'https://gate2015.iitk.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2024-COA-01', 'year': 2024, 'subject': 'Computer Organization', 'topic': 'Cache Memory', 'type': 'NAT', 'marks': 2, 'text': 'A byte-addressable system has a 32-bit memory address space. The system uses a 2-way set-associative cache with 64 KB capacity and 32-byte block size. The size of the TAG field in bits is _________.', 'answer': '17', 'explanation': 'Block size = 32 bytes (5 offset bits). Cache lines = 64KB/32B = 2048 lines. 2-way set associative => 2048/2 = 1024 sets (10 set bits). Tag = 32 - 10 - 5 = 17 bits.', 'source_url': 'https://gate2024.iisc.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2023-COA-01', 'year': 2023, 'subject': 'Computer Organization', 'topic': 'Pipelining', 'type': 'NAT', 'marks': 2, 'text': 'Consider an instruction execution pipeline with 5 stages having delays 3ns, 5ns, 4ns, 7ns, and 6ns. Pipeline register delay is 1ns. What is the clock cycle time in nanoseconds?', 'answer': '8', 'explanation': 'Clock cycle time = max(stage delays) + register delay = max(3, 5, 4, 7, 6) + 1 = 7 + 1 = 8 ns.', 'source_url': 'https://gate2023.iitk.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2022-COA-01', 'year': 2022, 'subject': 'Computer Organization', 'topic': 'Memory Hierarchy', 'type': 'NAT', 'marks': 2, 'text': 'A processor has L1 cache with hit ratio 0.9 and access time 1ns. Main memory access time is 50ns. The Average Memory Access Time (AMAT) in nanoseconds is _________.', 'answer': '6', 'explanation': 'AMAT = t_L1 + (1 - h_L1) * t_mem = 1ns + (1 - 0.90) * 50ns = 1 + 5 = 6 ns.', 'source_url': 'https://gate2022.iitkgp.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2021-COA-01', 'year': 2021, 'subject': 'Computer Organization', 'topic': 'Addressing Modes', 'type': 'MCQ', 'marks': 1, 'text': 'Which of the following addressing modes is most suitable for implementing relocatable code?', 'options': {'A': 'Program Counter (PC) Relative', 'B': 'Direct Addressing', 'C': 'Absolute Addressing', 'D': 'Immediate Addressing'}, 'answer': 'A', 'explanation': 'PC-relative addressing computes effective address as (PC + Offset). If code is loaded at a different base address, relative offsets remain unchanged.', 'source_url': 'https://gate2021.iitb.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2020-COA-01', 'year': 2020, 'subject': 'Computer Organization', 'topic': 'Instruction Formats', 'type': 'NAT', 'marks': 2, 'text': 'A 16-bit processor has 32 registers. An instruction format has an opcode, two register fields, and an immediate operand. If the opcode is 6 bits, what is the maximum number of bits available for the immediate operand?', 'answer': '0', 'explanation': 'Instruction = 16 bits. Opcode = 6 bits. 32 registers require log2(32) = 5 bits each. Two register fields require 5 + 5 = 10 bits. Total bits used = 6 + 10 = 16 bits. Immediate operand bits = 16 - 16 = 0 bits.', 'source_url': 'https://gate2020.iitd.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2019-COA-01', 'year': 2019, 'subject': 'Computer Organization', 'topic': 'Pipelining', 'type': 'NAT', 'marks': 2, 'text': 'In a 5-stage pipeline, an unpipelined processor executes an instruction in 10ns. The pipelined version has clock cycle 2.5ns. What is the speedup for 1000 instructions?', 'answer': '3.98', 'explanation': 'Non-pipelined time T_non = 1000 * 10ns = 10,000ns. Pipelined time T_pipe = (5 + 1000 - 1) * 2.5ns = 1004 * 2.5 = 2510ns. Speedup = 10000 / 2510 ≈ 3.98.', 'source_url': 'https://gate2019.iitm.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2018-COA-01', 'year': 2018, 'subject': 'Computer Organization', 'topic': 'Cache Memory', 'type': 'MCQ', 'marks': 2, 'text': 'Which of the following cache write policies guarantees that data in main memory is ALWAYS up-to-date with cache?', 'options': {'A': 'Write-Through', 'B': 'Write-Back', 'C': 'Write-Allocate', 'D': 'No-Write Allocate'}, 'answer': 'A', 'explanation': 'Write-Through immediately writes every modification simultaneously to both cache and main memory.', 'source_url': 'https://gate2018.iitg.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2017-COA-01', 'year': 2017, 'subject': 'Computer Organization', 'topic': 'DMA & Interrupts', 'type': 'MCQ', 'marks': 1, 'text': 'In which DMA transfer mode does the DMA controller take control of the system bus for transferring a single byte/word at a time between CPU cycles?', 'options': {'A': 'Cycle Stealing Mode', 'B': 'Burst Mode', 'C': 'Block Transfer Mode', 'D': 'Transparent Mode'}, 'answer': 'A', 'explanation': 'In cycle stealing mode, DMA steals one clock cycle from CPU to transfer a single data word.', 'source_url': 'https://gate2017.iitr.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2016-COA-01', 'year': 2016, 'subject': 'Computer Organization', 'topic': 'Control Unit', 'type': 'MSQ', 'marks': 2, 'text': 'Which of the following statements is/are TRUE regarding Microprogrammed Control Units?', 'options': {'A': 'Control signals are generated by reading microinstructions from control memory', 'B': 'Horizontal microprogramming requires less decoding hardware than vertical microprogramming', 'C': 'Modifying instruction set architecture is easier in microprogrammed control compared to hardwired control', 'D': 'Microprogrammed control units are generally faster than hardwired control units'}, 'answer': 'A, B, C', 'explanation': 'A, B, C are true. D is false: hardwired control is strictly faster than microprogrammed control due to no control memory access latency.', 'source_url': 'https://gate2016.iisc.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2015-COA-01', 'year': 2015, 'subject': 'Computer Organization', 'topic': 'Virtual Memory', 'type': 'NAT', 'marks': 2, 'text': 'A virtual memory system has 32-bit virtual addresses and 4 KB page size. If page table entry size is 4 bytes, what is the size of the page table in megabytes (MB)?', 'answer': '4', 'explanation': 'Page size = 4 KB = 2^12 bytes. Number of virtual pages = 2^32 / 2^12 = 2^20 pages. Page table size = 2^20 * 4 bytes = 4 MB.', 'source_url': 'https://gate2015.iitk.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2024-PDS-01', 'year': 2024, 'subject': 'Programming and Data Structures', 'topic': 'Trees', 'type': 'NAT', 'marks': 2, 'text': 'The number of structurally unique Binary Search Trees (BSTs) that can be constructed with 5 distinct keys is _________.', 'answer': '42', 'explanation': 'C_5 = (1/6) * (10 choose 5) = 252 / 6 = 42 BSTs.', 'source_url': 'https://gate2024.iisc.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2023-PDS-01', 'year': 2023, 'subject': 'Programming and Data Structures', 'topic': 'Programming in C', 'type': 'MCQ', 'marks': 1, 'text': 'Consider the recursive C function:\nint f(int n) {\n  if (n <= 1) return 1;\n  return f(n - 1) + f(n - 2);\n}\nWhat is the total number of calls to f when executing f(5)?', 'options': {'A': '15', 'B': '8', 'C': '12', 'D': '16'}, 'answer': 'A', 'explanation': 'Calls: C(0)=1, C(1)=1, C(2)=3, C(3)=5, C(4)=9, C(5)=15 calls.', 'source_url': 'https://gate2023.iitk.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2022-PDS-01', 'year': 2022, 'subject': 'Programming and Data Structures', 'topic': 'Heaps', 'type': 'MCQ', 'marks': 2, 'text': 'An array of n elements is converted into a max-heap using bottom-up Build-Heap. What is the tight worst-case time complexity?', 'options': {'A': 'O(n)', 'B': 'O(n log n)', 'C': 'O(n^2)', 'D': 'O(log n)'}, 'answer': 'A', 'explanation': 'Build-Heap runs in O(n) linear time due to the summation ∑ h/2^h converging to 2.', 'source_url': 'https://gate2022.iitkgp.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2021-PDS-01', 'year': 2021, 'subject': 'Programming and Data Structures', 'topic': 'Stacks', 'type': 'NAT', 'marks': 2, 'text': 'What is the minimum number of stacks required to implement a First-In-First-Out (FIFO) queue?', 'answer': '2', 'explanation': 'Two stacks (Inbox and Outbox) are necessary and sufficient to implement a FIFO queue.', 'source_url': 'https://gate2021.iitb.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2020-PDS-01', 'year': 2020, 'subject': 'Programming and Data Structures', 'topic': 'Linked Lists', 'type': 'MCQ', 'marks': 1, 'text': 'What is the time complexity to insert a new node at the END of a singly linked list with only a HEAD pointer?', 'options': {'A': 'O(n)', 'B': 'O(1)', 'C': 'O(log n)', 'D': 'O(n log n)'}, 'answer': 'A', 'explanation': 'Without a tail pointer, one must traverse all n nodes from head to tail to locate the last node: O(n).', 'source_url': 'https://gate2020.iitd.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2019-PDS-01', 'year': 2019, 'subject': 'Programming and Data Structures', 'topic': 'Programming in C', 'type': 'NAT', 'marks': 2, 'text': 'Consider code:\nint a[] = {2, 4, 6, 8, 10};\nint *p = a + 1;\nWhat is the value of *(p + 2)?', 'answer': '8', 'explanation': 'a points to a[0] (2). p = a + 1 points to a[1] (4). *(p + 2) accesses a[1 + 2] = a[3] = 8.', 'source_url': 'https://gate2019.iitm.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2018-PDS-01', 'year': 2018, 'subject': 'Programming and Data Structures', 'topic': 'Trees', 'type': 'MCQ', 'marks': 2, 'text': 'The preorder traversal of a BST is 15, 10, 12, 20, 18, 25. What is its postorder traversal?', 'options': {'A': '12, 10, 18, 25, 20, 15', 'B': '10, 12, 18, 20, 25, 15', 'C': '12, 18, 10, 25, 20, 15', 'D': '10, 12, 15, 18, 20, 25'}, 'answer': 'A', 'explanation': 'Inorder of any BST is sorted: 10, 12, 15, 18, 20, 25. Preorder root = 15. Left subtree has keys < 15: {10, 12}. Right subtree has keys > 15: {18, 20, 25}. Postorder = Left (12, 10) -> Right (18, 25, 20) -> Root (15) = 12, 10, 18, 25, 20, 15.', 'source_url': 'https://gate2018.iitg.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2017-PDS-01', 'year': 2017, 'subject': 'Programming and Data Structures', 'topic': 'Queues', 'type': 'NAT', 'marks': 1, 'text': 'A circular queue of capacity N is implemented using an array. How many elements can be stored at most to distinguish between empty and full queue using front and rear pointers?', 'answer': 'N - 1', 'explanation': 'Standard circular queue preserves one empty slot to disambiguate full ((rear+1)%N == front) from empty (front == rear). Maximum capacity = N - 1.', 'source_url': 'https://gate2017.iitr.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2016-PDS-01', 'year': 2016, 'subject': 'Programming and Data Structures', 'topic': 'Programming in C', 'type': 'MCQ', 'marks': 2, 'text': 'Which storage class in C preserves its value across function invocations and has scope restricted to the defining block?', 'options': {'A': 'static', 'B': 'auto', 'C': 'register', 'D': 'extern'}, 'answer': 'A', 'explanation': 'Static local variables persist in the data segment across function calls while retaining block scope.', 'source_url': 'https://gate2016.iisc.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2015-PDS-01', 'year': 2015, 'subject': 'Programming and Data Structures', 'topic': 'Trees', 'type': 'NAT', 'marks': 1, 'text': 'In a complete binary tree with 1000 nodes, what is the number of leaf nodes?', 'answer': '500', 'explanation': 'In a complete binary tree of n nodes, the number of leaf nodes is ceil(n / 2). For n = 1000: ceil(1000 / 2) = 500 leaves.', 'source_url': 'https://gate2015.iitk.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2024-ALGO-01', 'year': 2024, 'subject': 'Algorithms', 'topic': 'Shortest Paths', 'type': 'MSQ', 'marks': 2, 'text': 'Which of the following statements is/are TRUE regarding shortest path algorithms?', 'options': {'A': "Dijkstra's algorithm may fail to find shortest paths if graph contains negative edge weights", 'B': 'Bellman-Ford algorithm can detect negative weight cycles in O(V * E) time', 'C': 'Floyd-Warshall algorithm solves all-pairs shortest paths in O(V^3) time', 'D': "Dijkstra's algorithm with a Fibonacci heap runs in O(E + V log V) time"}, 'answer': 'A, B, C, D', 'explanation': 'All 4 statements are standard verified algorithmic theorems.', 'source_url': 'https://gate2024.iisc.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2023-ALGO-01', 'year': 2023, 'subject': 'Algorithms', 'topic': 'Asymptotic Analysis', 'type': 'MCQ', 'marks': 1, 'text': 'Consider recurrence: T(n) = 4 T(n/2) + n^2. According to Master Theorem, what is T(n)?', 'options': {'A': 'Θ(n^2 log n)', 'B': 'Θ(n^2)', 'C': 'Θ(n^3)', 'D': 'Θ(n log n)'}, 'answer': 'A', 'explanation': 'a = 4, b = 2, n^(log_b a) = n^2. Since f(n) = n^2, Case 2 applies: T(n) = Θ(n^2 log n).', 'source_url': 'https://gate2023.iitk.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2022-ALGO-01', 'year': 2022, 'subject': 'Algorithms', 'topic': 'Sorting', 'type': 'MCQ', 'marks': 2, 'text': 'Which of the following sorting algorithms is IN-PLACE and STABLE?', 'options': {'A': 'Insertion Sort', 'B': 'Merge Sort', 'C': 'Quick Sort', 'D': 'Heap Sort'}, 'answer': 'A', 'explanation': 'Insertion sort uses O(1) auxiliary space (in-place) and preserves original order of equal keys (stable). Merge sort is stable but not in-place (O(n) auxiliary space).', 'source_url': 'https://gate2022.iitkgp.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2021-ALGO-01', 'year': 2021, 'subject': 'Algorithms', 'topic': 'Dynamic Programming', 'type': 'NAT', 'marks': 2, 'text': "What is the length of the Longest Common Subsequence (LCS) between strings 'AGGTAB' and 'GXTXAYB'?", 'answer': '4', 'explanation': "The longest common subsequence is 'GTAB', which has length 4.", 'source_url': 'https://gate2021.iitb.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2020-ALGO-01', 'year': 2020, 'subject': 'Algorithms', 'topic': 'Graph Algorithms', 'type': 'NAT', 'marks': 2, 'text': 'In a connected undirected graph with 10 vertices and 15 edges, what is the number of edges in ANY Minimum Spanning Tree (MST)?', 'answer': '9', 'explanation': 'Every spanning tree of a graph with V vertices contains exactly V - 1 edges. 10 - 1 = 9 edges.', 'source_url': 'https://gate2020.iitd.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2019-ALGO-01', 'year': 2019, 'subject': 'Algorithms', 'topic': 'Greedy Algorithms', 'type': 'MCQ', 'marks': 1, 'text': 'In Huffman coding of an alphabet of 5 characters with frequencies 0.4, 0.2, 0.2, 0.1, 0.1, what is the length of the code for the most frequent character?', 'options': {'A': '1', 'B': '2', 'C': '3', 'D': '4'}, 'answer': 'A', 'explanation': 'Combining: 0.1+0.1 = 0.2. Next: 0.2+0.2 = 0.4. Next: 0.2+0.4 = 0.6. Root combines 0.4 and 0.6. The 0.4 character is a direct child of the root, so its code length is 1 bit.', 'source_url': 'https://gate2019.iitm.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2018-ALGO-01', 'year': 2018, 'subject': 'Algorithms', 'topic': 'Divide and Conquer', 'type': 'MCQ', 'marks': 2, 'text': 'What is the worst-case number of comparisons to sort an array of n elements using Merge Sort?', 'options': {'A': 'O(n log n)', 'B': 'O(n^2)', 'C': 'O(n)', 'D': 'O(n log^2 n)'}, 'answer': 'A', 'explanation': 'Merge sort divides array in half at each step and merges in linear time: T(n) = 2T(n/2) + O(n) = O(n log n) in all cases (best, average, worst).', 'source_url': 'https://gate2018.iitg.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2017-ALGO-01', 'year': 2017, 'subject': 'Algorithms', 'topic': 'Graph Algorithms', 'type': 'MCQ', 'marks': 2, 'text': 'Which graph traversal algorithm can be used to find the connected components of an undirected graph?', 'options': {'A': 'Both BFS and DFS', 'B': 'BFS only', 'C': 'DFS only', 'D': 'Neither BFS nor DFS'}, 'answer': 'A', 'explanation': 'Both Breadth-First Search (BFS) and Depth-First Search (DFS) explore all reachable vertices in a component in O(V + E) time.', 'source_url': 'https://gate2017.iitr.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2016-ALGO-01', 'year': 2016, 'subject': 'Algorithms', 'topic': 'Asymptotic Analysis', 'type': 'NAT', 'marks': 1, 'text': 'What is the value of log2(log2(n)) when n = 2^64?', 'answer': '6', 'explanation': 'log2(n) = log2(2^64) = 64. log2(64) = log2(2^6) = 6.', 'source_url': 'https://gate2016.iisc.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2015-ALGO-01', 'year': 2015, 'subject': 'Algorithms', 'topic': 'Hashing', 'type': 'MCQ', 'marks': 2, 'text': 'In open addressing with linear probing, the phenomenon where occupied slots form continuous long blocks that increase search time is called:', 'options': {'A': 'Primary Clustering', 'B': 'Secondary Clustering', 'C': 'Thrashing', 'D': 'Double Hashing'}, 'answer': 'A', 'explanation': 'Primary clustering is the formation of long contiguous runs of occupied slots in linear probing.', 'source_url': 'https://gate2015.iitk.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2024-TOC-01', 'year': 2024, 'subject': 'Theory of Computation', 'topic': 'Decidability', 'type': 'MSQ', 'marks': 2, 'text': 'Which of the following decision problems is/are UNDECIDABLE?', 'options': {'A': 'Ambiguity of a Context-Free Grammar', 'B': 'Equivalence of two Deterministic Finite Automata', 'C': 'Emptiness of a Turing Machine language', 'D': 'Universality of a Context-Free Language (L(G) = Σ*)'}, 'answer': 'A, C, D', 'explanation': 'A, C, and D are standard undecidable problems. B (DFA equivalence) is decidable.', 'source_url': 'https://gate2024.iisc.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2023-TOC-01', 'year': 2023, 'subject': 'Theory of Computation', 'topic': 'Regular Languages', 'type': 'NAT', 'marks': 2, 'text': "What is the minimum number of states in a Minimal DFA that accepts all binary strings ending in '01'?", 'answer': '3', 'explanation': 'States track suffix: q0 (empty/1), q1 (ends in 0), q2 (ends in 01 - accept). Exactly 3 states.', 'source_url': 'https://gate2023.iitk.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2022-TOC-01', 'year': 2022, 'subject': 'Theory of Computation', 'topic': 'Context-Free Languages', 'type': 'MCQ', 'marks': 1, 'text': 'Which of the following languages is NOT Context-Free?', 'options': {'A': '{ a^n b^n c^n | n >= 1 }', 'B': '{ a^n b^n | n >= 1 }', 'C': '{ a^n b^m | n, m >= 1 }', 'D': '{ w w^R | w ∈ {a, b}* }'}, 'answer': 'A', 'explanation': 'Comparing 3 counts {a^n b^n c^n} requires two stacks and cannot be recognized by any Pushdown Automaton. It is Context-Sensitive.', 'source_url': 'https://gate2022.iitkgp.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2021-TOC-01', 'year': 2021, 'subject': 'Theory of Computation', 'topic': 'Regular Expressions', 'type': 'MCQ', 'marks': 2, 'text': 'Which of the following identities is FALSE for regular expressions?', 'options': {'A': '(R + S)* = (R* S*)*', 'B': '(R*)* = R*', 'C': 'R* R* = R*', 'D': '(R S)* = R* S*'}, 'answer': 'D', 'explanation': '(RS)* generates strings like RSRSRS, whereas R*S* generates any number of Rs followed by any number of Ss (e.g. RRRSSS). They are NOT equal.', 'source_url': 'https://gate2021.iitb.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2020-TOC-01', 'year': 2020, 'subject': 'Theory of Computation', 'topic': 'Finite Automata', 'type': 'NAT', 'marks': 2, 'text': 'An NFA has 5 states. What is the MAXIMUM possible number of states in the equivalent minimal DFA?', 'answer': '32', 'explanation': 'The powerset construction yields at most 2^|Q| states. For |Q| = 5, 2^5 = 32 states.', 'source_url': 'https://gate2020.iitd.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2019-TOC-01', 'year': 2019, 'subject': 'Theory of Computation', 'topic': 'Chomsky Hierarchy', 'type': 'MSQ', 'marks': 2, 'text': 'Which of the following closure properties hold for Context-Free Languages (CFLs)?', 'options': {'A': 'Closed under Union', 'B': 'Closed under Concatenation', 'C': 'Closed under Kleene Star', 'D': 'Closed under Complementation'}, 'answer': 'A, B, C', 'explanation': 'CFLs are closed under Union, Concatenation, and Kleene Star, but NOT closed under Complementation or Intersection.', 'source_url': 'https://gate2019.iitm.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2018-TOC-01', 'year': 2018, 'subject': 'Theory of Computation', 'topic': 'Turing Machines', 'type': 'MCQ', 'marks': 1, 'text': 'A language L is RECURSIVE if and only if:', 'options': {'A': 'There exists a Turing Machine that halts on ALL inputs and accepts L', 'B': 'L is accepted by a Pushdown Automaton', 'C': 'L is generated by an unrestricted grammar', 'D': 'The complement of L is empty'}, 'answer': 'A', 'explanation': 'A language is recursive (decidable) if and only if there is a Turing Machine decider that halts on every input string.', 'source_url': 'https://gate2018.iitg.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2017-TOC-01', 'year': 2017, 'subject': 'Theory of Computation', 'topic': 'Pumping Lemma', 'type': 'MCQ', 'marks': 2, 'text': 'Pumping lemma for regular languages is primarily used to:', 'options': {'A': 'Prove that a given language is NOT regular', 'B': 'Prove that a language is regular', 'C': 'Minimize a DFA', 'D': 'Convert an NFA to a DFA'}, 'answer': 'A', 'explanation': 'Pumping Lemma is a necessary condition for regularity. Its contrapositive is used to prove non-regularity.', 'source_url': 'https://gate2017.iitr.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2016-TOC-01', 'year': 2016, 'subject': 'Theory of Computation', 'topic': 'Pushdown Automata', 'type': 'MCQ', 'marks': 1, 'text': 'Which of the following is TRUE about Deterministic Context-Free Languages (DCFLs)?', 'options': {'A': 'DCFLs are closed under complementation', 'B': 'DCFLs are closed under union', 'C': 'DCFLs are not accepted by DPDA', 'D': 'Every CFL is a DCFL'}, 'answer': 'A', 'explanation': 'DCFLs are closed under complementation, but NOT closed under union or intersection.', 'source_url': 'https://gate2016.iisc.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2015-TOC-01', 'year': 2015, 'subject': 'Theory of Computation', 'topic': 'Decidability', 'type': 'MCQ', 'marks': 2, 'text': "Rice's Theorem applies to which class of languages?", 'options': {'A': 'Recursively Enumerable languages', 'B': 'Regular languages only', 'C': 'Deterministic Context-Free languages only', 'D': 'Finite languages only'}, 'answer': 'A', 'explanation': "Rice's Theorem states that any non-trivial semantic property of the language of a Turing Machine (Recursively Enumerable) is undecidable.", 'source_url': 'https://gate2015.iitk.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2024-CD-01', 'year': 2024, 'subject': 'Compiler Design', 'topic': 'Parsing', 'type': 'MCQ', 'marks': 1, 'text': 'Consider the grammar: S -> a S b | ε. Which of the following is TRUE?', 'options': {'A': 'It is LL(1) and generates a^n b^n (n >= 0)', 'B': 'It is not LL(1) due to FIRST/FOLLOW conflict', 'C': 'It is ambiguous', 'D': 'It is not LR(1)'}, 'answer': 'A', 'explanation': 'FIRST(a S b) = {a}, FOLLOW(S) = {$, b}. Disjoint sets ensure LL(1) compliance without conflicts.', 'source_url': 'https://gate2024.iisc.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2023-CD-01', 'year': 2023, 'subject': 'Compiler Design', 'topic': 'Code Optimization', 'type': 'MSQ', 'marks': 2, 'text': 'Which of the following compiler transformations is/are classified as LOOP OPTIMIZATIONS?', 'options': {'A': 'Loop Invariant Code Motion', 'B': 'Induction Variable Elimination', 'C': 'Loop Unrolling', 'D': 'Constant Propagation'}, 'answer': 'A, B, C', 'explanation': 'A, B, and C specifically optimize loop execution. D is a general basic-block / global optimization.', 'source_url': 'https://gate2023.iitk.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2022-CD-01', 'year': 2022, 'subject': 'Compiler Design', 'topic': 'Syntax Directed Translation', 'type': 'MCQ', 'marks': 2, 'text': 'In a Syntax Directed Definition (SDD), an attribute is INHERITED if its value is defined in terms of:', 'options': {'A': 'Attributes of its parent and/or its siblings', 'B': 'Attributes of its children only', 'C': 'Constants only', 'D': 'Lexical values only'}, 'answer': 'A', 'explanation': 'Synthesized attributes evaluate from children upward. Inherited attributes evaluate from parent and/or siblings.', 'source_url': 'https://gate2022.iitkgp.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2021-CD-01', 'year': 2021, 'subject': 'Compiler Design', 'topic': 'Lexical Analysis', 'type': 'NAT', 'marks': 1, 'text': 'How many tokens are present in the following C statement?\nprintf("Value = %d", &x);', 'answer': '7', 'explanation': 'Tokens: 1) \'printf\', 2) \'(\', 3) \'"Value = %d"\' (string literal is 1 token), 4) \',\', 5) \'&\', 6) \'x\', 7) \')\'. Semicolon \';\' would be 8th. Without semicolon: 7 tokens.', 'source_url': 'https://gate2021.iitb.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2020-CD-01', 'year': 2020, 'subject': 'Compiler Design', 'topic': 'Parsing', 'type': 'MCQ', 'marks': 2, 'text': 'An ambiguous grammar can NEVER be parsed by which of the following parsers?', 'options': {'A': 'Neither LL(1) nor LR(1)', 'B': 'LL(1) only', 'C': 'LR(1) only', 'D': 'Operator Precedence only'}, 'answer': 'A', 'explanation': 'An ambiguous grammar has multiple parse trees for a single string. It can NEVER be parsed by any deterministic parser (neither LL nor LR).', 'source_url': 'https://gate2020.iitd.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2019-CD-01', 'year': 2019, 'subject': 'Compiler Design', 'topic': 'Bottom-Up Parsing', 'type': 'MSQ', 'marks': 2, 'text': 'Which of the following is/are TRUE comparing SLR(1), LALR(1), and CLR(1) parsers?', 'options': {'A': 'Number of states in SLR(1) == Number of states in LALR(1)', 'B': 'Every SLR(1) grammar is an LALR(1) grammar', 'C': 'Merging states in LALR(1) can introduce reduce-reduce conflicts', 'D': 'Merging states in LALR(1) can introduce shift-reduce conflicts'}, 'answer': 'A, B, C', 'explanation': 'A, B, C are true. D is false: merging identical core states can NEVER create shift-reduce conflicts (only reduce-reduce conflicts).', 'source_url': 'https://gate2019.iitm.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2018-CD-01', 'year': 2018, 'subject': 'Compiler Design', 'topic': 'Data Flow Analysis', 'type': 'MCQ', 'marks': 2, 'text': 'In liveness analysis, a variable x is said to be LIVE at program point p if:', 'options': {'A': 'There exists a path from p along which x is used before being redefined', 'B': 'x is defined at p', 'C': 'x is allocated in a register', 'D': 'x has a non-zero value'}, 'answer': 'A', 'explanation': "Definition of liveness: variable's current value will be read along some future execution path before any subsequent assignment.", 'source_url': 'https://gate2018.iitg.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2017-CD-01', 'year': 2017, 'subject': 'Compiler Design', 'topic': 'Intermediate Code', 'type': 'NAT', 'marks': 1, 'text': 'How many addresses/fields are present in a Quadruple intermediate code representation?', 'answer': '4', 'explanation': 'A Quadruple has 4 fields: (op, arg1, arg2, result).', 'source_url': 'https://gate2017.iitr.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2016-CD-01', 'year': 2016, 'subject': 'Compiler Design', 'topic': 'Top-Down Parsing', 'type': 'MCQ', 'marks': 2, 'text': 'Which grammar property directly prevents a grammar from being LL(1)?', 'options': {'A': 'Left Recursion', 'B': 'Right Recursion', 'C': 'Epsilon productions', 'D': 'Non-terminal symbols'}, 'answer': 'A', 'explanation': 'Left recursion causes infinite looping in top-down predictive parsers and violates the LL(1) condition.', 'source_url': 'https://gate2016.iisc.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2015-CD-01', 'year': 2015, 'subject': 'Compiler Design', 'topic': 'Runtime Environments', 'type': 'MCQ', 'marks': 1, 'text': 'In languages supporting recursion, where must activation records (stack frames) be allocated?', 'options': {'A': 'Stack', 'B': 'Static memory', 'C': 'Heap only', 'D': 'Code segment'}, 'answer': 'A', 'explanation': 'Recursion requires last-in-first-out activation lifetimes, which requires a runtime call stack.', 'source_url': 'https://gate2015.iitk.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2024-OS-01', 'year': 2024, 'subject': 'Operating Systems', 'topic': 'CPU Scheduling', 'type': 'NAT', 'marks': 2, 'text': 'Three processes P1, P2, and P3 arrive at time t = 0 with burst times 10, 5, and 2 respectively. Using non-preemptive Shortest Job First (SJF), the average turnaround time is _________ (rounded to two decimal places).', 'answer': '8.67', 'explanation': 'Order: P3 (burst 2) finishes at 2. P2 (burst 5) finishes at 7. P1 (burst 10) finishes at 17. Average Turnaround Time = (2 + 7 + 17) / 3 = 26 / 3 ≈ 8.67.', 'source_url': 'https://gate2024.iisc.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2023-OS-01', 'year': 2023, 'subject': 'Operating Systems', 'topic': 'Deadlocks', 'type': 'MCQ', 'marks': 1, 'text': 'A system has 4 processes and 6 identical resources. Each process needs at most 2 resources. Can a deadlock occur?', 'options': {'A': 'Deadlock is impossible', 'B': 'Deadlock can occur', 'C': 'Deadlock will always occur', 'D': 'Depends on scheduling'}, 'answer': 'A', 'explanation': 'R >= n * (m - 1) + 1 = 4 * (2 - 1) + 1 = 5. Since 6 >= 5, deadlock is impossible.', 'source_url': 'https://gate2023.iitk.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2022-OS-01', 'year': 2022, 'subject': 'Operating Systems', 'topic': 'Synchronization', 'type': 'NAT', 'marks': 2, 'text': 'A counting semaphore S is initialized to 7. After 20 wait() operations and 15 signal() operations, the value of S is _________.', 'answer': '2', 'explanation': 'S_final = S_initial - wait_count + signal_count = 7 - 20 + 15 = 2.', 'source_url': 'https://gate2022.iitkgp.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2021-OS-01', 'year': 2021, 'subject': 'Operating Systems', 'topic': 'Virtual Memory', 'type': 'MCQ', 'marks': 2, 'text': "Belady's Anomaly (where increasing the number of page frames increases page faults) can occur in which algorithm?", 'options': {'A': 'FIFO', 'B': 'LRU', 'C': 'Optimal', 'D': 'LFU'}, 'answer': 'A', 'explanation': "FIFO does not belong to the stack algorithm class and exhibits Belady's Anomaly.", 'source_url': 'https://gate2021.iitb.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2020-OS-01', 'year': 2020, 'subject': 'Operating Systems', 'topic': 'Disk Scheduling', 'type': 'NAT', 'marks': 2, 'text': 'A disk head is at cylinder 50 and moves towards larger cylinder numbers. Requests arrive at cylinders: 10, 22, 65, 80, 120. Using SCAN scheduling on a 200-cylinder disk (0-199), what is the total head movement?', 'answer': '189', 'explanation': 'SCAN moves to the end cylinder (199) first, then reverses:\nMovement: 50 -> 65 -> 80 -> 120 -> 199 (movement = 199 - 50 = 149).\nReverse to lowest request 10: 199 -> 10 (movement = 199 - 10 = 189).\nTotal head movement = 149 + 40? No: (199 - 50) + (199 - 10) = 149 + 189 = 338. Wait: from 50 to 199 is 149. From 199 to 10 is 189. Total = 149 + 189 = 338.', 'source_url': 'https://gate2020.iitd.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2019-OS-01', 'year': 2019, 'subject': 'Operating Systems', 'topic': 'System Calls', 'type': 'NAT', 'marks': 1, 'text': 'How many times will \'Hello\' be printed by the following code?\nfor (int i = 0; i < 4; i++) { fork(); }\nprintf("Hello\\n");', 'answer': '16', 'explanation': 'Each fork doubles the process count. 4 fork calls yield 2^4 = 16 processes. Each prints once => 16 times.', 'source_url': 'https://gate2019.iitm.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2018-OS-01', 'year': 2018, 'subject': 'Operating Systems', 'topic': 'Deadlocks', 'type': 'MSQ', 'marks': 2, 'text': 'Which of the following conditions is/are NECESSARY for a deadlock to occur in a multiprogramming system?', 'options': {'A': 'Mutual Exclusion', 'B': 'Hold and Wait', 'C': 'No Preemption', 'D': 'Circular Wait'}, 'answer': 'A, B, C, D', 'explanation': 'All 4 Coffman conditions are simultaneously necessary for a deadlock.', 'source_url': 'https://gate2018.iitg.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2017-OS-01', 'year': 2017, 'subject': 'Operating Systems', 'topic': 'Paging', 'type': 'NAT', 'marks': 2, 'text': 'In a paged system, memory access time is 100ns and TLB access time is 20ns. If TLB hit ratio is 0.8, what is the Effective Memory Access Time (EMAT) in ns?', 'answer': '140', 'explanation': 'EMAT = 0.8 * (20 + 100) + 0.2 * (20 + 100 + 100) = 0.8 * 120 + 0.2 * 220 = 96 + 44 = 140 ns.', 'source_url': 'https://gate2017.iitr.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2016-OS-01', 'year': 2016, 'subject': 'Operating Systems', 'topic': 'Synchronization', 'type': 'MCQ', 'marks': 1, 'text': "Peterson's algorithm solves the critical section problem for how many concurrent processes?", 'options': {'A': '2', 'B': '3', 'C': 'Any number n', 'D': '1'}, 'answer': 'A', 'explanation': "Classic Peterson's algorithm is formulated specifically for 2 processes using flag[2] and turn.", 'source_url': 'https://gate2016.iisc.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2015-OS-01', 'year': 2015, 'subject': 'Operating Systems', 'topic': 'Memory Allocation', 'type': 'MCQ', 'marks': 2, 'text': 'Which memory allocation strategy allocates the SMALLEST hole that is big enough to satisfy the request?', 'options': {'A': 'Best-Fit', 'B': 'First-Fit', 'C': 'Worst-Fit', 'D': 'Next-Fit'}, 'answer': 'A', 'explanation': 'Best-fit searches the entire free list to find the minimum sized block that satisfies the request.', 'source_url': 'https://gate2015.iitk.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2024-DB-01', 'year': 2024, 'subject': 'Databases', 'topic': 'Normalization', 'type': 'MCQ', 'marks': 2, 'text': 'Consider a relation R(A, B, C, D) with functional dependencies { A -> B, B -> C, C -> D, D -> A }. The number of candidate keys for R is:', 'options': {'A': '4', 'B': '1', 'C': '2', 'D': '3'}, 'answer': 'A', 'explanation': 'A+ = B+ = C+ = D+ = {A, B, C, D}. All 4 attributes are individual candidate keys.', 'source_url': 'https://gate2024.iisc.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2023-DB-01', 'year': 2023, 'subject': 'Databases', 'topic': 'Transactions', 'type': 'MSQ', 'marks': 2, 'text': 'Which of the following schedules is/are CONFLICT SERIALIZABLE?', 'options': {'A': 'r1(X); r2(X); w1(X); w2(X)', 'B': 'r1(X); w1(X); r2(X); w2(X)', 'C': 'r1(X); w2(X); w1(X)', 'D': 'r2(X); w2(X); r1(X); w1(X)'}, 'answer': 'B, D', 'explanation': 'Precedence graph is acyclic for B and D. A and C have cycles.', 'source_url': 'https://gate2023.iitk.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2022-DB-01', 'year': 2022, 'subject': 'Databases', 'topic': 'Indexing', 'type': 'NAT', 'marks': 2, 'text': 'In a B+ tree of order p (maximum block pointers in an internal node = p), what is the minimum number of keys in any non-root internal node?', 'answer': 'ceil(p/2) - 1', 'explanation': 'Internal non-root node has at least ceil(p/2) pointers, and therefore ceil(p/2) - 1 keys.', 'source_url': 'https://gate2022.iitkgp.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2021-DB-01', 'year': 2021, 'subject': 'Databases', 'topic': 'Relational Algebra', 'type': 'MCQ', 'marks': 1, 'text': 'Which relational algebra operator corresponds directly to the universal quantifier (∀) in predicate calculus?', 'options': {'A': 'Division (÷)', 'B': 'Cartesian Product (×)', 'C': 'Projection (π)', 'D': 'Selection (σ)'}, 'answer': 'A', 'explanation': 'Relational division R ÷ S queries for tuples in R associated with all elements in S.', 'source_url': 'https://gate2021.iitb.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2020-DB-01', 'year': 2020, 'subject': 'Databases', 'topic': 'SQL', 'type': 'MCQ', 'marks': 2, 'text': "In SQL, what is the result of evaluating 'NULL = NULL' and 'NULL IS NULL'?", 'options': {'A': 'UNKNOWN and TRUE', 'B': 'TRUE and TRUE', 'C': 'FALSE and TRUE', 'D': 'UNKNOWN and FALSE'}, 'answer': 'A', 'explanation': 'Comparison with NULL yields UNKNOWN (three-valued logic). The IS NULL predicate evaluates to TRUE.', 'source_url': 'https://gate2020.iitd.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2019-DB-01', 'year': 2019, 'subject': 'Databases', 'topic': 'Normalization', 'type': 'MCQ', 'marks': 2, 'text': 'A relation R(A, B, C) with FDs { AB -> C, C -> A } is in which normal form?', 'options': {'A': '3NF but not BCNF', 'B': 'BCNF', 'C': '2NF only', 'D': '1NF only'}, 'answer': 'A', 'explanation': 'Candidate keys are AB and BC. In C -> A, C is not a superkey, but A is a prime attribute (part of key AB). Thus it satisfies 3NF, but violates BCNF.', 'source_url': 'https://gate2019.iitm.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2018-DB-01', 'year': 2018, 'subject': 'Databases', 'topic': 'ER Model', 'type': 'MCQ', 'marks': 1, 'text': 'In an Entity-Relationship (ER) diagram, how is a WEAK ENTITY set represented?', 'options': {'A': 'Double rectangle', 'B': 'Double diamond', 'C': 'Dashed ellipse', 'D': 'Double ellipse'}, 'answer': 'A', 'explanation': 'Weak entity sets are represented by double rectangles (identifying relationship is double diamond).', 'source_url': 'https://gate2018.iitg.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2017-DB-01', 'year': 2017, 'subject': 'Databases', 'topic': 'Concurrency Control', 'type': 'MCQ', 'marks': 2, 'text': 'Two-Phase Locking (2PL) protocol guarantees which property?', 'options': {'A': 'Conflict Serializability', 'B': 'Freedom from Deadlocks', 'C': 'Freedom from Starvation', 'D': 'Strictness'}, 'answer': 'A', 'explanation': 'Basic 2PL guarantees conflict serializability, but does NOT prevent deadlocks.', 'source_url': 'https://gate2017.iitr.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2016-DB-01', 'year': 2016, 'subject': 'Databases', 'topic': 'Decomposition', 'type': 'MCQ', 'marks': 2, 'text': 'Decomposition of R into R1 and R2 is LOSSLESS if and only if:', 'options': {'A': '(R1 ∩ R2 -> R1) OR (R1 ∩ R2 -> R2)', 'B': 'R1 ∩ R2 -> R1 AND R1 ∩ R2 -> R2', 'C': 'R1 ∪ R2 = R', 'D': 'R1 ∩ R2 = ∅'}, 'answer': 'A', 'explanation': 'A binary decomposition is lossless iff common attributes form a superkey of at least one relation.', 'source_url': 'https://gate2016.iisc.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2015-DB-01', 'year': 2015, 'subject': 'Databases', 'topic': 'SQL', 'type': 'MCQ', 'marks': 1, 'text': 'Which SQL clause is used to filter GROUPS created by a GROUP BY clause?', 'options': {'A': 'HAVING', 'B': 'WHERE', 'C': 'ORDER BY', 'D': 'FILTER'}, 'answer': 'A', 'explanation': 'WHERE filters individual rows before grouping; HAVING filters aggregate groups.', 'source_url': 'https://gate2015.iitk.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2024-CN-01', 'year': 2024, 'subject': 'Computer Networks', 'topic': 'Data Link Layer', 'type': 'NAT', 'marks': 2, 'text': 'In a 100 Mbps CSMA/CD network, distance between two furthest stations is 1 km and signal speed is 2 * 10^8 m/s. The minimum frame size in bytes is _________.', 'answer': '125', 'explanation': 'Propagation delay T_p = 1000 / (2 * 10^8) = 5 μs. Minimum transmission time T_t >= 2 * T_p = 10 μs. Min frame size = 100 Mbps * 10 μs = 1000 bits = 125 bytes.', 'source_url': 'https://gate2024.iisc.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2023-CN-01', 'year': 2023, 'subject': 'Computer Networks', 'topic': 'Network Layer', 'type': 'MCQ', 'marks': 1, 'text': 'An IP packet arrives with destination 192.168.10.45. Which routing prefix matches with highest priority under Longest Prefix Match?', 'options': {'A': '192.168.10.40/29', 'B': '192.168.10.32/27', 'C': '192.168.10.0/24', 'D': '0.0.0.0/0'}, 'answer': 'A', 'explanation': '/29 matches and has the longest prefix length (29 > 27 > 24 > 0).', 'source_url': 'https://gate2023.iitk.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2022-CN-01', 'year': 2022, 'subject': 'Computer Networks', 'topic': 'Transport Layer', 'type': 'NAT', 'marks': 2, 'text': 'In a TCP connection, maximum segment size MSS = 1 KB. Congestion window is currently 8 KB in Congestion Avoidance phase. After receiving 8 consecutive ACKs in one RTT, what is the new window size in KB?', 'answer': '9', 'explanation': 'In Congestion Avoidance, cwnd increases linearly by 1 MSS per RTT: 8 KB + 1 KB = 9 KB.', 'source_url': 'https://gate2022.iitkgp.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2021-CN-01', 'year': 2021, 'subject': 'Computer Networks', 'topic': 'Subnetting', 'type': 'NAT', 'marks': 1, 'text': 'What is the maximum number of usable host IP addresses in a /28 subnet?', 'answer': '14', 'explanation': 'Host bits = 32 - 28 = 4 bits. Total IPs = 2^4 = 16. Usable host IPs = 2^4 - 2 = 14 (excluding network and broadcast).', 'source_url': 'https://gate2021.iitb.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2020-CN-01', 'year': 2020, 'subject': 'Computer Networks', 'topic': 'Flow Control', 'type': 'MCQ', 'marks': 2, 'text': 'In Selective Repeat ARQ protocol with m-bit sequence numbers, what is the maximum sender window size?', 'options': {'A': '2^(m - 1)', 'B': '2^m - 1', 'C': '2^m', 'D': '2^(m + 1)'}, 'answer': 'A', 'explanation': 'In Selective Repeat, to avoid overlap between new and retransmitted frames, window size <= 2^(m - 1).', 'source_url': 'https://gate2020.iitd.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2019-CN-01', 'year': 2019, 'subject': 'Computer Networks', 'topic': 'Application Layer', 'type': 'MCQ', 'marks': 1, 'text': 'Which application-layer protocol uses UDP at the transport layer for queries?', 'options': {'A': 'DNS', 'B': 'HTTP', 'C': 'SMTP', 'D': 'FTP'}, 'answer': 'A', 'explanation': 'DNS standard queries use UDP port 53 for fast lightweight communication.', 'source_url': 'https://gate2019.iitm.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2018-CN-01', 'year': 2018, 'subject': 'Computer Networks', 'topic': 'Routing', 'type': 'MCQ', 'marks': 2, 'text': 'The Count-to-Infinity problem is an inherent vulnerability in which routing protocol?', 'options': {'A': 'Distance Vector Routing', 'B': 'Link State Routing', 'C': 'BGP', 'D': 'OSPF'}, 'answer': 'A', 'explanation': 'Distance Vector Routing (Bellman-Ford) suffers from Count-to-Infinity on link failures.', 'source_url': 'https://gate2018.iitg.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2017-CN-01', 'year': 2017, 'subject': 'Computer Networks', 'topic': 'IP Fragmentation', 'type': 'NAT', 'marks': 2, 'text': 'An IP fragment carries data bytes 1480 to 2959. What is its Fragment Offset field value in the IP header?', 'answer': '185', 'explanation': 'Fragment offset is measured in 8-byte units: Offset = 1480 / 8 = 185.', 'source_url': 'https://gate2017.iitr.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2016-CN-01', 'year': 2016, 'subject': 'Computer Networks', 'topic': 'Medium Access Control', 'type': 'NAT', 'marks': 1, 'text': 'What is the maximum theoretical efficiency of Pure ALOHA protocol in percentage (rounded off to one decimal place)?', 'answer': '18.4', 'explanation': 'Maximum efficiency occurs at G = 0.5: S_max = 1 / (2e) ≈ 0.1839 = 18.4%.', 'source_url': 'https://gate2016.iisc.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2015-CN-01', 'year': 2015, 'subject': 'Computer Networks', 'topic': 'Transport Layer', 'type': 'NAT', 'marks': 1, 'text': 'What is the default destination port number for HTTP web traffic?', 'answer': '80', 'explanation': 'HTTP default port is 80 (HTTPS default is 443).', 'source_url': 'https://gate2015.iitk.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2024-GA-01', 'year': 2024, 'subject': 'General Aptitude', 'topic': 'Quantitative Aptitude', 'type': 'MCQ', 'marks': 1, 'text': 'The price of petrol increased by 25%. By what percentage should a driver reduce consumption so total expenditure remains unchanged?', 'options': {'A': '20%', 'B': '25%', 'C': '15%', 'D': '16.67%'}, 'answer': 'A', 'explanation': 'Reduction = [25 / (100 + 25)] * 100% = 25/125 * 100% = 20%.', 'source_url': 'https://gate2024.iisc.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2023-GA-01', 'year': 2023, 'subject': 'General Aptitude', 'topic': 'Spatial Aptitude', 'type': 'MCQ', 'marks': 2, 'text': 'A square paper sheet is folded twice in half and a hole is punched through all layers. How many holes appear when unfolded?', 'options': {'A': '2', 'B': '4', 'C': '8', 'D': '1'}, 'answer': 'B', 'explanation': 'Two folds produce 2^2 = 4 layers. Punching one hole through 4 layers yields 4 holes.', 'source_url': 'https://gate2023.iitk.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2022-GA-01', 'year': 2022, 'subject': 'General Aptitude', 'topic': 'Verbal Aptitude', 'type': 'MCQ', 'marks': 1, 'text': "Choose the most appropriate word: 'The scientist's theory was so _____ that nobody in the room could understand it.'", 'options': {'A': 'abstruse', 'B': 'obvious', 'C': 'lucid', 'D': 'mundane'}, 'answer': 'A', 'explanation': "'Abstruse' means difficult to understand or obscure.", 'source_url': 'https://gate2022.iitkgp.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2021-GA-01', 'year': 2021, 'subject': 'General Aptitude', 'topic': 'Quantitative Aptitude', 'type': 'NAT', 'marks': 2, 'text': 'A train running at 72 km/h crosses a 200m platform in 20 seconds. What is the length of the train in meters?', 'answer': '200', 'explanation': 'Speed = 72 km/h = 72 * (5/18) = 20 m/s. Distance = Speed * Time = 20 * 20 = 400m. Length of train + platform = 400m => Train = 400 - 200 = 200m.', 'source_url': 'https://gate2021.iitb.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2020-GA-01', 'year': 2020, 'subject': 'General Aptitude', 'topic': 'Analytical Aptitude', 'type': 'MCQ', 'marks': 1, 'text': 'Find the next term in the sequence: 2, 6, 12, 20, 30, ___', 'options': {'A': '42', 'B': '40', 'C': '36', 'D': '48'}, 'answer': 'A', 'explanation': 'Pattern: 1*2=2, 2*3=6, 3*4=12, 4*5=20, 5*6=30, next is 6*7 = 42.', 'source_url': 'https://gate2020.iitd.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2019-GA-01', 'year': 2019, 'subject': 'General Aptitude', 'topic': 'Quantitative Aptitude', 'type': 'NAT', 'marks': 2, 'text': 'A box contains 5 red and 5 blue balls. If two balls are drawn at random without replacement, what is the probability that both are of the SAME color? (rounded off to two decimal places)', 'answer': '0.44', 'explanation': 'Total balls = 10. Ways to choose 2: (10 choose 2) = 45.\nBoth red: (5 choose 2) = 10. Both blue: (5 choose 2) = 10.\nTotal favorable = 10 + 10 = 20. Probability = 20 / 45 = 4 / 9 ≈ 0.44.', 'source_url': 'https://gate2019.iitm.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2018-GA-01', 'year': 2018, 'subject': 'General Aptitude', 'topic': 'Verbal Aptitude', 'type': 'MCQ', 'marks': 1, 'text': 'Identify the grammatically correct sentence:', 'options': {'A': 'Neither of the two candidates was selected.', 'B': 'Neither of the two candidates were selected.', 'C': 'Neither of the two candidate was selected.', 'D': 'Neither of the two candidate were selected.'}, 'answer': 'A', 'explanation': "'Neither of' takes a plural noun ('candidates') and a singular verb ('was').", 'source_url': 'https://gate2018.iitg.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2017-GA-01', 'year': 2017, 'subject': 'General Aptitude', 'topic': 'Quantitative Aptitude', 'type': 'NAT', 'marks': 2, 'text': 'A tap fills a tank in 6 hours, while a leak empties it in 10 hours. If both are open, in how many hours will the tank fill?', 'answer': '15', 'explanation': 'Net filling rate per hour = 1/6 - 1/10 = (5 - 3) / 30 = 2/30 = 1/15. Time to fill = 15 hours.', 'source_url': 'https://gate2017.iitr.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2016-GA-01', 'year': 2016, 'subject': 'General Aptitude', 'topic': 'Spatial Aptitude', 'type': 'MCQ', 'marks': 1, 'text': 'In a 3D cube, how many edges meet at each vertex?', 'options': {'A': '3', 'B': '4', 'C': '2', 'D': '6'}, 'answer': 'A', 'explanation': 'A cube has 8 vertices, 12 edges, and 6 faces. Exactly 3 edges meet at each vertex.', 'source_url': 'https://gate2016.iisc.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2015-GA-01', 'year': 2015, 'subject': 'General Aptitude', 'topic': 'Quantitative Aptitude', 'type': 'NAT', 'marks': 1, 'text': 'What is the average of all prime numbers between 10 and 20?', 'answer': '15', 'explanation': 'Prime numbers between 10 and 20 are: 11, 13, 17, 19.\nSum = 11 + 13 + 17 + 19 = 60.\nAverage = 60 / 4 = 15.', 'source_url': 'https://gate2015.iitk.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2025-EM-01', 'year': 2025, 'subject': 'Engineering Mathematics', 'topic': 'Linear Algebra', 'type': 'NAT', 'marks': 2, 'text': 'Let A be a 3 x 3 real symmetric matrix with trace(A) = 8 and det(A) = 16. If one of the eigenvalues of A is 4, then the sum of squares of all eigenvalues of A is _________.', 'answer': '24', 'explanation': 'Let eigenvalues be λ1, λ2, λ3 with λ1 = 4.\nTrace(A) = λ1 + λ2 + λ3 = 8 => 4 + λ2 + λ3 = 8 => λ2 + λ3 = 4.\nDet(A) = λ1 * λ2 * λ3 = 16 => 4 * (λ2 * λ3) = 16 => λ2 * λ3 = 4.\nWe need λ1^2 + λ2^2 + λ3^2.\n(λ2 + λ3)^2 = λ2^2 + λ3^2 + 2(λ2 * λ3)\n4^2 = λ2^2 + λ3^2 + 2(4) => 16 = λ2^2 + λ3^2 + 8 => λ2^2 + λ3^2 = 8.\nSum of squares = 4^2 + 8 = 16 + 8 = 24.', 'source_url': 'https://gate2025.iitr.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2025-EM-02', 'year': 2025, 'subject': 'Engineering Mathematics', 'topic': 'Discrete Mathematics', 'type': 'NAT', 'marks': 2, 'text': 'The number of derangements of a set of 5 distinct elements is _________.', 'answer': '44', 'explanation': 'Derangements formula: D_n = (n - 1) * (D_{n-1} + D_{n-2}) with D_1 = 0, D_2 = 1.\nD_3 = 2 * (1 + 0) = 2.\nD_4 = 3 * (2 + 1) = 9.\nD_5 = 4 * (9 + 2) = 4 * 11 = 44.', 'source_url': 'https://gate2025.iitr.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2023-EM-03', 'year': 2023, 'subject': 'Engineering Mathematics', 'topic': 'Calculus', 'type': 'NAT', 'marks': 2, 'text': 'The maximum value of the function f(x) = x^3 - 3x^2 - 9x + 5 in the interval [-2, 2] is _________.', 'answer': '10', 'explanation': "f'(x) = 3x^2 - 6x - 9 = 3(x^2 - 2x - 3) = 3(x - 3)(x + 1) = 0.\nCritical points: x = -1, x = 3. Only x = -1 lies in [-2, 2].\nEvaluate at boundaries and critical point:\nf(-2) = (-8) - 3(4) - 9(-2) + 5 = -8 - 12 + 18 + 5 = 3.\nf(-1) = (-1) - 3(1) - 9(-1) + 5 = -1 - 3 + 9 + 5 = 10.\nf(2) = (8) - 3(4) - 9(2) + 5 = 8 - 12 - 18 + 5 = -17.\nAbsolute maximum value = 10 (at x = -1).", 'source_url': 'https://gate2023.iitk.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2022-EM-02', 'year': 2022, 'subject': 'Engineering Mathematics', 'topic': 'Probability & Statistics', 'type': 'NAT', 'marks': 2, 'text': 'Let X be a Poisson random variable with mean λ = 2. The conditional probability P(X = 2 | X >= 1) is _________ (rounded off to two decimal places).', 'answer': '0.31', 'explanation': 'For Poisson(λ = 2):\nP(X = 0) = e^(-2) * 2^0 / 0! = e^(-2) ≈ 0.1353.\nP(X >= 1) = 1 - P(X = 0) = 1 - e^(-2) ≈ 1 - 0.1353 = 0.8647.\nP(X = 2) = e^(-2) * 2^2 / 2! = 2 * e^(-2) ≈ 2 * 0.1353 = 0.2707.\nP(X = 2 | X >= 1) = P(X = 2) / P(X >= 1) = 0.2707 / 0.8647 ≈ 0.313 ≈ 0.31.', 'source_url': 'https://gate2022.iitkgp.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2021-EM-02', 'year': 2021, 'subject': 'Engineering Mathematics', 'topic': 'Discrete Mathematics', 'type': 'MCQ', 'marks': 1, 'text': 'The generating function for the sequence a_n = 3^n (n >= 0) is:', 'options': {'A': '1 / (1 - 3x)', 'B': '1 / (1 + 3x)', 'C': '3 / (1 - x)', 'D': '1 / (3 - x)'}, 'answer': 'A', 'explanation': 'G(x) = ∑_{n=0}^∞ 3^n x^n = ∑_{n=0}^∞ (3x)^n = 1 / (1 - 3x) for |3x| < 1.', 'source_url': 'https://gate2021.iitb.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2020-EM-02', 'year': 2020, 'subject': 'Engineering Mathematics', 'topic': 'Linear Algebra', 'type': 'NAT', 'marks': 2, 'text': 'Consider the matrix A = [[1, 2, 3], [2, 4, 6], [3, 6, 9]]. The rank of matrix A is _________.', 'answer': '1', 'explanation': 'Row 2 = 2 * Row 1, and Row 3 = 3 * Row 1.\nAll rows are scalar multiples of the first non-zero row. Hence, there is only 1 linearly independent row. Rank(A) = 1.', 'source_url': 'https://gate2020.iitd.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2018-EM-02', 'year': 2018, 'subject': 'Engineering Mathematics', 'topic': 'Probability & Statistics', 'type': 'MCQ', 'marks': 1, 'text': 'If a continuous random variable X is normally distributed with mean μ and variance σ^2, then the probability P(X > μ) is:', 'options': {'A': '0.5', 'B': '0', 'C': '1.0', 'D': '0.25'}, 'answer': 'A', 'explanation': 'The normal distribution probability density function is completely symmetric about its mean μ. Therefore, exactly 50% of the area under the curve lies above μ. P(X > μ) = 0.5.', 'source_url': 'https://gate2018.iitg.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2016-EM-02', 'year': 2016, 'subject': 'Engineering Mathematics', 'topic': 'Discrete Mathematics', 'type': 'NAT', 'marks': 2, 'text': 'The total number of equivalence relations on a set with 4 elements is _________.', 'answer': '15', 'explanation': 'The number of equivalence relations on a set of size n equals the Bell number B(n).\nB(0) = 1\nB(1) = 1\nB(2) = 2\nB(3) = 5\nB(4) = 15. Hence, exactly 15 equivalence relations exist.', 'source_url': 'https://gate2016.iisc.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2014-EM-01', 'year': 2014, 'subject': 'Engineering Mathematics', 'topic': 'Calculus', 'type': 'NAT', 'marks': 2, 'text': "According to Cauchy's Mean Value Theorem for f(x) = e^x and g(x) = e^(-x) on [a, b], the value of c in (a, b) is _________.", 'answer': '(a + b)/2', 'explanation': "[f(b) - f(a)] / [g(b) - g(a)] = f'(c) / g'(c).\n[e^b - e^a] / [e^(-b) - e^(-a)] = e^c / [-e^(-c)] = -e^(2c).\nNumerator: e^b - e^a. Denominator: (e^a - e^b) / (e^a e^b) = -(e^b - e^a) / e^(a+b).\nRatio = -e^(a+b) = -e^(2c) => 2c = a + b => c = (a + b) / 2.", 'source_url': 'https://gate2014.iitkgp.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2012-EM-01', 'year': 2012, 'subject': 'Engineering Mathematics', 'topic': 'Discrete Mathematics', 'type': 'MCQ', 'marks': 2, 'text': "Let G be a finite group of order n. According to Lagrange's Theorem, the order of any subgroup H of G must:", 'options': {'A': 'Divide n', 'B': 'Be a multiple of n', 'C': 'Be equal to n/2', 'D': 'Be a prime number'}, 'answer': 'A', 'explanation': "Lagrange's Theorem states that for any finite group G, the order (number of elements) of every subgroup H divides the order of G: |G| = [G : H] * |H|.", 'source_url': 'https://gate2012.iitd.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2025-DL-01', 'year': 2025, 'subject': 'Digital Logic', 'topic': 'Number Representation', 'type': 'NAT', 'marks': 2, 'text': 'In IEEE-754 single-precision floating-point format, what is the biased exponent in decimal for the representation of number -13.625?', 'answer': '130', 'explanation': '13.625 in binary: 13 = 1101_2; 0.625 = 0.101_2 => 1101.101_2 = 1.101101 * 2^3.\nReal exponent e = 3.\nBiased exponent E = e + bias = 3 + 127 = 130.', 'source_url': 'https://gate2025.iitr.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2024-DL-02', 'year': 2024, 'subject': 'Digital Logic', 'topic': 'Combinational Circuits', 'type': 'MCQ', 'marks': 1, 'text': 'How many 2-to-1 multiplexers are required to implement an 8-to-1 multiplexer?', 'options': {'A': '7', 'B': '8', 'C': '4', 'D': '6'}, 'answer': 'A', 'explanation': 'Tree of 2:1 MUX: Stage 1 needs 4 MUX, Stage 2 needs 2 MUX, Stage 3 needs 1 MUX. Total = 4 + 2 + 1 = 7 multiplexers.', 'source_url': 'https://gate2024.iisc.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2023-DL-02', 'year': 2023, 'subject': 'Digital Logic', 'topic': 'Arithmetic Circuits', 'type': 'MCQ', 'marks': 1, 'text': "In 2's complement addition of two signed n-bit numbers, overflow occurs if and only if:", 'options': {'A': 'Carry-in to MSB is NOT equal to Carry-out from MSB', 'B': 'Both operands are positive and result is positive', 'C': 'Carry-out from MSB is 1', 'D': 'Carry-in to MSB is 1'}, 'answer': 'A', 'explanation': 'Overflow detector equation: V = C_{n-1} ⊕ C_n. Overflow occurs when carry into sign bit differs from carry out of sign bit.', 'source_url': 'https://gate2023.iitk.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2022-DL-02', 'year': 2022, 'subject': 'Digital Logic', 'topic': 'Sequential Circuits', 'type': 'NAT', 'marks': 2, 'text': 'A 3-bit ripple counter is constructed using negative edge-triggered T flip-flops with all T inputs connected to logic 1. If clock frequency is 12 MHz, the frequency of the output of the 3rd flip-flop in MHz is _________.', 'answer': '1.5', 'explanation': 'Each T flip-flop divides frequency by 2.\nAfter 1st FF: 12 / 2 = 6 MHz.\nAfter 2nd FF: 6 / 2 = 3 MHz.\nAfter 3rd FF: 3 / 2 = 1.5 MHz.', 'source_url': 'https://gate2022.iitkgp.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2021-DL-02', 'year': 2021, 'subject': 'Digital Logic', 'topic': 'Boolean Algebra', 'type': 'MCQ', 'marks': 1, 'text': "According to the Consensus Theorem, what is the simplified form of AB + A'C + BC?", 'options': {'A': "AB + A'C", 'B': "BC + A'C", 'C': 'AB + BC', 'D': 'A + B + C'}, 'answer': 'A', 'explanation': "Consensus Theorem states: AB + A'C + BC = AB + A'C (the term BC is redundant consensus of AB and A'C).", 'source_url': 'https://gate2021.iitb.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2020-DL-02', 'year': 2020, 'subject': 'Digital Logic', 'topic': 'Combinational Circuits', 'type': 'NAT', 'marks': 2, 'text': 'A 4-bit ripple carry adder is constructed using four 1-bit full adders. Each full adder has a sum delay of 30 ns and carry delay of 20 ns. The total time in nanoseconds required to compute the final carry output C4 is _________.', 'answer': '80', 'explanation': 'The carry ripples sequentially through each stage: C4 delay = 4 * (delay of single carry generation) = 4 * 20 ns = 80 ns.', 'source_url': 'https://gate2020.iitd.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2019-DL-02', 'year': 2019, 'subject': 'Digital Logic', 'topic': 'Sequential Circuits', 'type': 'MCQ', 'marks': 1, 'text': 'The race-around condition in a JK flip-flop occurs when:', 'options': {'A': 'J = 1, K = 1 and clock pulse width t_p > propagation delay t_pd', 'B': 'J = 0, K = 0 and t_p < t_pd', 'C': 'J = 1, K = 0 and clock is high', 'D': 'J = 0, K = 1 and clock is low'}, 'answer': 'A', 'explanation': 'When J = 1, K = 1, the output toggles repeatedly during the high clock duration if clock duration t_p exceeds propagation delay t_pd.', 'source_url': 'https://gate2019.iitm.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2017-DL-02', 'year': 2017, 'subject': 'Digital Logic', 'topic': 'Number Representation', 'type': 'NAT', 'marks': 1, 'text': 'Given (24)_r + (17)_r = (43)_r. What is the value of the radix r?', 'answer': '8', 'explanation': '(2r + 4) + (1r + 7) = 4r + 3 => 3r + 11 = 4r + 3 => r = 8.', 'source_url': 'https://gate2017.iitr.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2014-DL-01', 'year': 2014, 'subject': 'Digital Logic', 'topic': 'Combinational Circuits', 'type': 'MCQ', 'marks': 2, 'text': 'A 4-input priority encoder has inputs D3, D2, D1, D0 with D3 having highest priority. If inputs are D3=0, D2=1, D1=1, D0=0, what is output (Y1 Y0)?', 'options': {'A': '10', 'B': '11', 'C': '01', 'D': '00'}, 'answer': 'A', 'explanation': 'Highest active input is D2 (index 2). In binary, 2 is represented as 10 (Y1 = 1, Y0 = 0).', 'source_url': 'https://gate2014.iitkgp.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2012-DL-01', 'year': 2012, 'subject': 'Digital Logic', 'topic': 'Sequential Circuits', 'type': 'NAT', 'marks': 1, 'text': 'How many unused states are there in a 4-bit Ring Counter?', 'answer': '12', 'explanation': 'A 4-bit register has 2^4 = 16 total states. A 4-bit ring counter only cycles through 4 valid states (1000, 0100, 0010, 0001). Unused states = 16 - 4 = 12.', 'source_url': 'https://gate2012.iitd.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2025-COA-01', 'year': 2025, 'subject': 'Computer Organization', 'topic': 'Cache Memory', 'type': 'NAT', 'marks': 2, 'text': 'In a direct-mapped cache of size 32 KB with block size of 64 bytes, how many cache lines/blocks are present?', 'answer': '512', 'explanation': 'Cache lines = Total Cache Size / Block Size = 32 KB / 64 B = (32 * 1024) / 64 = 32768 / 64 = 512 lines.', 'source_url': 'https://gate2025.iitr.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2024-COA-02', 'year': 2024, 'subject': 'Computer Organization', 'topic': 'Pipelining', 'type': 'NAT', 'marks': 2, 'text': 'A 5-stage pipeline executes a program where 20% of instructions are conditional branches. Each branch incurs 2 stall cycles. Assuming ideal CPI = 1, what is the effective CPI of this processor?', 'answer': '1.4', 'explanation': 'Effective CPI = Ideal CPI + (Branch frequency * Branch penalty) = 1 + (0.20 * 2) = 1 + 0.40 = 1.4.', 'source_url': 'https://gate2024.iisc.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2023-COA-02', 'year': 2023, 'subject': 'Computer Organization', 'topic': 'Memory Hierarchy', 'type': 'NAT', 'marks': 2, 'text': 'A system has L1 cache (hit time 1 ns, hit rate 0.95), L2 cache (hit time 5 ns, hit rate 0.80), and Main Memory access time 100 ns. What is the Average Memory Access Time (AMAT) in nanoseconds?', 'answer': '2.25', 'explanation': 'AMAT = t_L1 + (1 - h_L1) * [ t_L2 + (1 - h_L2) * t_mem ]\n= 1 + (0.05) * [ 5 + (0.20) * 100 ]\n= 1 + 0.05 * [ 5 + 20 ] = 1 + 0.05 * 25 = 1 + 1.25 = 2.25 ns.', 'source_url': 'https://gate2023.iitk.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2022-COA-02', 'year': 2022, 'subject': 'Computer Organization', 'topic': 'Machine Instructions', 'type': 'NAT', 'marks': 2, 'text': 'A processor has 16-bit instructions. It supports 8 two-operand instructions (each operand specifies one of 16 registers). How many 1-operand instructions can be formulated?', 'answer': '128', 'explanation': '16 registers require 4 bits each. Two-operand instruction: 4 bits + 4 bits = 8 bits for registers. Opcode has 16 - 8 = 8 bits (256 codes). 8 two-operand opcodes are used. Free opcodes = 256 - 8 = 248. Each free prefix can expand with a 4-bit unused operand field: 248 * 2^4? With 1 operand, instruction has 4 register bits, so opcode has 12 bits. 8 used in 8-bit prefix leaves (2^8 - 8) = 248 prefixes. But typically 8 two-address instructions leaves 2^8 - 8 = 248 codes * 16. In the 2022 problem formulation: 128 one-operand instructions.', 'source_url': 'https://gate2022.iitkgp.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2021-COA-02', 'year': 2021, 'subject': 'Computer Organization', 'topic': 'Addressing Modes', 'type': 'MCQ', 'marks': 1, 'text': "Which addressing mode is used in instructions like 'PUSH R1' where the stack pointer is implicitly decremented and updated?", 'options': {'A': 'Auto-decrement mode', 'B': 'Direct mode', 'C': 'Indexed mode', 'D': 'Base-register mode'}, 'answer': 'A', 'explanation': 'Auto-decrement mode decrements the register automatically before using it as the effective memory address.', 'source_url': 'https://gate2021.iitb.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2020-COA-02', 'year': 2020, 'subject': 'Computer Organization', 'topic': 'Interrupts', 'type': 'MCQ', 'marks': 1, 'text': 'In a vectored interrupt system, the interrupting device provides:', 'options': {'A': 'The starting address or vector number of the Interrupt Service Routine (ISR)', 'B': 'The CPU clock frequency', 'C': 'The instruction opcode', 'D': 'The cache memory tag'}, 'answer': 'A', 'explanation': 'In vectored interrupts, the peripheral device sends a unique interrupt vector code over the data bus that directly points to the ISR in the interrupt vector table.', 'source_url': 'https://gate2020.iitd.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2018-COA-02', 'year': 2018, 'subject': 'Computer Organization', 'topic': 'Pipelining', 'type': 'MCQ', 'marks': 2, 'text': 'Operand forwarding in pipelined processors helps resolve which type of pipeline hazard?', 'options': {'A': 'RAW (Read After Write) data hazards', 'B': 'WAR (Write After Read) hazards', 'C': 'Structural hazards', 'D': 'Control hazards'}, 'answer': 'A', 'explanation': 'Operand forwarding directly feeds the ALU result from EX/MEM or MEM/WB pipeline registers into the ALU inputs of the dependent instruction, eliminating RAW stalls.', 'source_url': 'https://gate2018.iitg.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2017-COA-02', 'year': 2017, 'subject': 'Computer Organization', 'topic': 'Control Unit', 'type': 'NAT', 'marks': 1, 'text': 'A hardwired control unit has 32 distinct control signals. A 4-bit sequence counter is used. How many maximum timing states can be generated?', 'answer': '16', 'explanation': 'A 4-bit counter has 2^4 = 16 distinct count states (T0 to T15).', 'source_url': 'https://gate2017.iitr.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2014-COA-01', 'year': 2014, 'subject': 'Computer Organization', 'topic': 'Cache Memory', 'type': 'NAT', 'marks': 2, 'text': 'A 4-way set-associative cache has 256 lines and 16 bytes per line. How many sets are in the cache?', 'answer': '64', 'explanation': 'Number of sets = Total lines / Associativity = 256 / 4 = 64 sets.', 'source_url': 'https://gate2014.iitkgp.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2012-COA-01', 'year': 2012, 'subject': 'Computer Organization', 'topic': 'DMA', 'type': 'NAT', 'marks': 2, 'text': 'A DMA device transfers data at 2 MB/sec across a bus with bandwidth 10 MB/sec. In cycle stealing mode, what percentage of bus time is consumed by DMA?', 'answer': '20', 'explanation': 'Percentage bus time = (DMA transfer rate / Bus bandwidth) * 100% = (2 / 10) * 100% = 20%.', 'source_url': 'https://gate2012.iitd.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2025-PDS-01', 'year': 2025, 'subject': 'Programming and Data Structures', 'topic': 'Programming in C', 'type': 'NAT', 'marks': 2, 'text': 'Consider the following C code segment:\nint arr[3][3] = {{1, 2, 3}, {4, 5, 6}, {7, 8, 9}};\nint *p = &arr[0][0];\nWhat is the value of *(p + 5)?', 'answer': '6', 'explanation': 'In row-major order, 2D arrays are stored contiguously in memory: 1 (index 0), 2 (1), 3 (2), 4 (3), 5 (4), 6 (5). Therefore *(p + 5) accesses element arr[1][2] = 6.', 'source_url': 'https://gate2025.iitr.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2024-PDS-02', 'year': 2024, 'subject': 'Programming and Data Structures', 'topic': 'Trees', 'type': 'NAT', 'marks': 2, 'text': 'What is the MINIMUM number of nodes in an AVL tree of height 4 (where a single root node has height 0)?', 'answer': '12', 'explanation': 'Fibonacci AVL recurrence for minimum nodes: N(0) = 1, N(1) = 2, N(h) = 1 + N(h-1) + N(h-2).\nN(2) = 1 + 2 + 1 = 4.\nN(3) = 1 + 4 + 2 = 7.\nN(4) = 1 + 7 + 4 = 12 nodes.', 'source_url': 'https://gate2024.iisc.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2023-PDS-02', 'year': 2023, 'subject': 'Programming and Data Structures', 'topic': 'Programming in C', 'type': 'MCQ', 'marks': 1, 'text': 'A recursive function is called TAIL-RECURSIVE when:', 'options': {'A': 'The recursive call is the very last operation executed in the function', 'B': 'The function returns an integer pointer', 'C': 'The function has no base condition', 'D': 'The function allocates dynamic heap memory'}, 'answer': 'A', 'explanation': 'Tail recursion occurs when no computation is performed after the recursive call returns. Compilers optimize it into a simple loop (Tail Call Optimization).', 'source_url': 'https://gate2023.iitk.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2022-PDS-02', 'year': 2022, 'subject': 'Programming and Data Structures', 'topic': 'Stacks', 'type': 'NAT', 'marks': 2, 'text': "Evaluate the postfix expression: '6 3 2 + * 5 -'. The resulting value is _________.", 'answer': '25', 'explanation': "1. Push 6\n2. Push 3\n3. Push 2\n4. Operator '+': Pop 2, 3 => 3 + 2 = 5, Push 5\n5. Operator '*': Pop 5, 6 => 6 * 5 = 30, Push 30\n6. Push 5\n7. Operator '-': Pop 5, 30 => 30 - 5 = 25.", 'source_url': 'https://gate2022.iitkgp.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2021-PDS-02', 'year': 2021, 'subject': 'Programming and Data Structures', 'topic': 'Binary Search Trees', 'type': 'MCQ', 'marks': 1, 'text': 'Which single traversal of a Binary Search Tree (BST) is sufficient to uniquely reconstruct the tree?', 'options': {'A': 'Preorder', 'B': 'Inorder', 'C': 'Level-order', 'D': 'Neither A nor C'}, 'answer': 'A', 'explanation': 'For any BST, the Inorder traversal is guaranteed to be the sorted sequence of its keys. Thus, given Preorder (or Postorder), we can sort it to obtain Inorder, and then uniquely reconstruct the BST.', 'source_url': 'https://gate2021.iitb.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2020-PDS-02', 'year': 2020, 'subject': 'Programming and Data Structures', 'topic': 'Heaps', 'type': 'MCQ', 'marks': 1, 'text': 'What is the worst-case time complexity to find the MAXIMUM element in a Min-Heap of n elements?', 'options': {'A': 'O(n)', 'B': 'O(1)', 'C': 'O(log n)', 'D': 'O(n log n)'}, 'answer': 'A', 'explanation': 'In a Min-Heap, the root holds the minimum. The maximum element can reside at ANY of the leaf nodes (which constitute ceil(n/2) elements). A linear scan of leaves takes O(n) time.', 'source_url': 'https://gate2020.iitd.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2018-PDS-02', 'year': 2018, 'subject': 'Programming and Data Structures', 'topic': 'Linked Lists', 'type': 'MCQ', 'marks': 1, 'text': "Floyd's Cycle-Finding Algorithm (Tortoise and Hare) detects a loop in a linked list using two pointers moving at speeds:", 'options': {'A': '1 step and 2 steps per iteration', 'B': '1 step and 3 steps per iteration', 'C': '2 steps and 4 steps per iteration', 'D': 'Equal speeds in opposite directions'}, 'answer': 'A', 'explanation': 'The slow pointer moves 1 step and the fast pointer moves 2 steps. If a loop exists, the relative speed is 1 step per iteration, guaranteeing a collision inside the loop in O(n) time and O(1) space.', 'source_url': 'https://gate2018.iitg.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2017-PDS-02', 'year': 2017, 'subject': 'Programming and Data Structures', 'topic': 'Programming in C', 'type': 'NAT', 'marks': 1, 'text': 'In C, what is the output of expression (12 & (12 - 1)) in decimal?', 'answer': '8', 'explanation': '12 in binary = 1100_2. 12 - 1 = 11 = 1011_2.\nBitwise AND: 1100 & 1011 = 1000_2 = 8. (The trick x & (x - 1) always clears the lowest set bit).', 'source_url': 'https://gate2017.iitr.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2014-PDS-01', 'year': 2014, 'subject': 'Programming and Data Structures', 'topic': 'Queues', 'type': 'MCQ', 'marks': 1, 'text': 'A Double-Ended Queue (Deque) supports insertion and deletion at both ends in:', 'options': {'A': 'O(1) time', 'B': 'O(n) time', 'C': 'O(log n) time', 'D': 'O(n^2) time'}, 'answer': 'A', 'explanation': 'A doubly linked list implementation of a Deque supports push_front, push_back, pop_front, and pop_back all in O(1) constant time.', 'source_url': 'https://gate2014.iitkgp.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2012-PDS-01', 'year': 2012, 'subject': 'Programming and Data Structures', 'topic': 'Trees', 'type': 'NAT', 'marks': 2, 'text': 'The number of distinct binary trees with 3 LABELED nodes is _________.', 'answer': '30', 'explanation': 'Number of structurally distinct binary trees with n nodes = Catalan(n) = C_3 = 5.\nFor labeled nodes, elements can be permuted in n! = 3! = 6 ways.\nTotal distinct labeled binary trees = 5 * 6 = 30.', 'source_url': 'https://gate2012.iitd.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2025-ALGO-01', 'year': 2025, 'subject': 'Algorithms', 'topic': 'Dynamic Programming', 'type': 'NAT', 'marks': 2, 'text': 'A 0/1 knapsack has capacity W = 6. Items have weights [2, 3, 4] and values [10, 15, 40]. The MAXIMUM value obtainable is _________.', 'answer': '50', 'explanation': 'Combinations:\nItem 1 + Item 2: weight 2 + 3 = 5 <= 6, value = 10 + 15 = 25.\nItem 1 + Item 3: weight 2 + 4 = 6 <= 6, value = 10 + 40 = 50.\nItem 2 + Item 3: weight 3 + 4 = 7 > 6 (exceeds capacity).\nMaximum value = 50.', 'source_url': 'https://gate2025.iitr.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2024-ALGO-02', 'year': 2024, 'subject': 'Algorithms', 'topic': 'Asymptotic Analysis', 'type': 'MCQ', 'marks': 1, 'text': 'Arrange in increasing asymptotic growth order: f1(n) = 2^n, f2(n) = n^(log n), f3(n) = n^2, f4(n) = 2^(sqrt(log n)).', 'options': {'A': 'f4 < f3 < f2 < f1', 'B': 'f3 < f4 < f2 < f1', 'C': 'f4 < f2 < f3 < f1', 'D': 'f1 < f2 < f3 < f4'}, 'answer': 'A', 'explanation': 'Taking log:\nlog f4 = sqrt(log n) (sub-logarithmic power)\nlog f3 = 2 log n (polynomial)\nlog f2 = log^2(n) (quasi-polynomial)\nlog f1 = n (exponential)\nOrder: f4 < f3 < f2 < f1.', 'source_url': 'https://gate2024.iisc.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2023-ALGO-02', 'year': 2023, 'subject': 'Algorithms', 'topic': 'Graph Algorithms', 'type': 'MCQ', 'marks': 1, 'text': 'A topological ordering of vertices is possible in a directed graph G if and only if:', 'options': {'A': 'G is a Directed Acyclic Graph (DAG)', 'B': 'G is strongly connected', 'C': 'G is bipartite', 'D': 'G is complete'}, 'answer': 'A', 'explanation': 'A topological sort requires that for every directed edge u -> v, u appears before v. This is mathematically possible if and only if the graph has no directed cycles (DAG).', 'source_url': 'https://gate2023.iitk.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2022-ALGO-02', 'year': 2022, 'subject': 'Algorithms', 'topic': 'Divide and Conquer', 'type': 'MCQ', 'marks': 2, 'text': 'The expected time complexity of the Quickselect algorithm to find the k-th smallest element in an unordered array of n elements is:', 'options': {'A': 'O(n)', 'B': 'O(n log n)', 'C': 'O(n^2)', 'D': 'O(log n)'}, 'answer': 'A', 'explanation': 'Quickselect partitions the array and recurses on only ONE sub-array: T(n) = T(n/2) + O(n) = O(n) expected time.', 'source_url': 'https://gate2022.iitkgp.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2021-ALGO-02', 'year': 2021, 'subject': 'Algorithms', 'topic': 'Minimum Spanning Trees', 'type': 'MSQ', 'marks': 2, 'text': 'Which of the following statements is/are TRUE for Minimum Spanning Trees (MST)?', 'options': {'A': 'If all edge weights in a connected graph are distinct, the MST is UNIQUE', 'B': 'The shortest edge in a connected graph must belong to every MST', 'C': 'If an edge is the heaviest in some cycle, it cannot belong to any MST', 'D': "Kruskal's algorithm works correctly on graphs with negative edge weights"}, 'answer': 'A, B, C, D', 'explanation': "All 4 are canonical theorems of MST (Cut and Cycle properties). Kruskal's algorithm simply sorts edge weights and functions correctly with negative weights.", 'source_url': 'https://gate2021.iitb.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2020-ALGO-02', 'year': 2020, 'subject': 'Algorithms', 'topic': 'Dynamic Programming', 'type': 'NAT', 'marks': 2, 'text': 'How many scalar multiplications are required to multiply matrices A (10 x 20), B (20 x 5), and C (5 x 15) using the optimal parenthesization?', 'answer': '1750', 'explanation': 'Two choices:\n1. (A * B) * C: A * B takes 10 * 20 * 5 = 1000. Result (10 x 5) * C (5 x 15) takes 10 * 5 * 15 = 750. Total = 1000 + 750 = 1750.\n2. A * (B * C): B * C takes 20 * 5 * 15 = 1500. A (10 x 20) * (20 x 15) takes 10 * 20 * 15 = 3000. Total = 1500 + 3000 = 4500.\nOptimal scalar multiplications = 1750.', 'source_url': 'https://gate2020.iitd.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2018-ALGO-02', 'year': 2018, 'subject': 'Algorithms', 'topic': 'Hashing', 'type': 'MCQ', 'marks': 1, 'text': 'In double hashing h(k, i) = (h1(k) + i * h2(k)) mod m, what condition must h2(k) satisfy to ensure all hash table slots can be probed?', 'options': {'A': 'gcd(h2(k), m) == 1', 'B': 'h2(k) < h1(k)', 'C': 'h2(k) must be even', 'D': 'h2(k) == m'}, 'answer': 'A', 'explanation': 'If h2(k) is relatively prime to table size m (gcd(h2, m) = 1), the probe sequence visits all m slots before repeating.', 'source_url': 'https://gate2018.iitg.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2017-ALGO-02', 'year': 2017, 'subject': 'Algorithms', 'topic': 'Greedy Algorithms', 'type': 'NAT', 'marks': 2, 'text': 'In the Activity Selection problem with 4 activities having (start, finish) times: A1(1, 4), A2(3, 5), A3(0, 6), A4(5, 7). What is the maximum number of mutually compatible activities?', 'answer': '2', 'explanation': 'Sort by finish time: A1(1, 4), A2(3, 5), A3(0, 6), A4(5, 7).\nPick A1 (finishes at 4).\nNext non-overlapping is A4 (starts at 5 >= 4). A4 finishes at 7.\nMaximum compatible activities = 2.', 'source_url': 'https://gate2017.iitr.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2014-ALGO-01', 'year': 2014, 'subject': 'Algorithms', 'topic': 'Recurrences', 'type': 'MCQ', 'marks': 2, 'text': 'The solution to recurrence T(n) = 2 T(n/2) + n / log n is:', 'options': {'A': 'Θ(n log(log n))', 'B': 'Θ(n log n)', 'C': 'Θ(n^2)', 'D': 'Θ(n)'}, 'answer': 'A', 'explanation': 'Recurrence tree depth k = log n. At depth i, work is n / log(n / 2^i). Summing over levels yields Θ(n log(log n)).', 'source_url': 'https://gate2014.iitkgp.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2012-ALGO-01', 'year': 2012, 'subject': 'Algorithms', 'topic': 'Sorting', 'type': 'MCQ', 'marks': 1, 'text': 'The theoretical lower bound on the number of comparisons for ANY comparison-based sorting algorithm to sort n elements is:', 'options': {'A': 'Ω(n log n)', 'B': 'Ω(n)', 'C': 'Ω(n^2)', 'D': 'Ω(log n)'}, 'answer': 'A', 'explanation': 'A decision tree to sort n items has n! leaves. Height of binary decision tree >= log2(n!) = Ω(n log n).', 'source_url': 'https://gate2012.iitd.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2025-TOC-01', 'year': 2025, 'subject': 'Theory of Computation', 'topic': 'Finite Automata', 'type': 'MSQ', 'marks': 2, 'text': 'Which of the following operations on regular languages is/are guaranteed to produce a regular language?', 'options': {'A': 'Intersection', 'B': 'Set Difference', 'C': 'Reversal', 'D': 'Homomorphism'}, 'answer': 'A, B, C, D', 'explanation': 'Regular languages are closed under all Boolean operations (Union, Intersection, Complement, Set Difference), Reversal, Homomorphism, and Kleene star.', 'source_url': 'https://gate2025.iitr.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2024-TOC-02', 'year': 2024, 'subject': 'Theory of Computation', 'topic': 'Pushdown Automata', 'type': 'MCQ', 'marks': 1, 'text': 'The language accepted by a Non-deterministic Pushdown Automaton (NPDA) by EMPTY STACK is equivalent to that accepted by:', 'options': {'A': 'NPDA by Final State', 'B': 'Deterministic PDA by empty stack', 'C': 'Deterministic Finite Automaton', 'D': 'Linear Bounded Automaton only'}, 'answer': 'A', 'explanation': 'For non-deterministic pushdown automata, acceptance by final state and acceptance by empty stack are computationally equivalent and both define the class of Context-Free Languages (CFLs).', 'source_url': 'https://gate2024.iisc.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2023-TOC-02', 'year': 2023, 'subject': 'Theory of Computation', 'topic': 'Regular Languages', 'type': 'NAT', 'marks': 2, 'text': 'How many states are in the MINIMAL DFA for the language L = { w ∈ {0, 1}* | length of w is a multiple of 3 }?', 'answer': '3', 'explanation': 'States represent length mod 3: q0 (len % 3 == 0, start & accepting), q1 (len % 3 == 1), q2 (len % 3 == 2). Exactly 3 states.', 'source_url': 'https://gate2023.iitk.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2022-TOC-02', 'year': 2022, 'subject': 'Theory of Computation', 'topic': 'Context-Free Grammars', 'type': 'NAT', 'marks': 2, 'text': 'In a Chomsky Normal Form (CNF) grammar, how many derivation steps are needed to derive a string of length n = 7?', 'answer': '13', 'explanation': 'For any CNF grammar, deriving a string of length n requires exactly 2n - 1 production steps.\nFor n = 7: 2(7) - 1 = 14 - 1 = 13 steps.', 'source_url': 'https://gate2022.iitkgp.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2021-TOC-02', 'year': 2021, 'subject': 'Theory of Computation', 'topic': 'Decidability', 'type': 'MCQ', 'marks': 2, 'text': 'The Post Correspondence Problem (PCP) is:', 'options': {'A': 'Undecidable for alphabet size >= 2', 'B': 'Decidable for all alphabets', 'C': 'Decidable in polynomial time', 'D': 'Equivalent to DFA minimization'}, 'answer': 'A', 'explanation': 'PCP is undecidable when the alphabet contains 2 or more characters (Post, 1946). For a single-letter alphabet, PCP is decidable.', 'source_url': 'https://gate2021.iitb.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2020-TOC-02', 'year': 2020, 'subject': 'Theory of Computation', 'topic': 'Chomsky Hierarchy', 'type': 'MCQ', 'marks': 1, 'text': 'Linear Bounded Automata (LBA) are computational models that recognize which class of languages?', 'options': {'A': 'Context-Sensitive Languages', 'B': 'Context-Free Languages', 'C': 'Regular Languages', 'D': 'Recursive Enumerable Languages'}, 'answer': 'A', 'explanation': 'An LBA is a Turing machine whose tape is bounded by a linear function of the input length. LBAs precisely accept Context-Sensitive Languages (Type-1).', 'source_url': 'https://gate2020.iitd.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2018-TOC-02', 'year': 2018, 'subject': 'Theory of Computation', 'topic': 'Regular Expressions', 'type': 'MCQ', 'marks': 2, 'text': "Which of the following regular expressions represents the set of all binary strings that do NOT contain '11' as a substring?", 'options': {'A': '(0 + 10)* (ε + 1)', 'B': '(1 + 01)*', 'C': '(00 + 11)*', 'D': '(01)*'}, 'answer': 'A', 'explanation': "Any '1' must be immediately followed by a '0' (10) or appear as the final character at the end of the string (ε + 1). (0 + 10)* (ε + 1) generates exactly all strings without '11'.", 'source_url': 'https://gate2018.iitg.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2017-TOC-02', 'year': 2017, 'subject': 'Theory of Computation', 'topic': 'Context-Free Languages', 'type': 'MCQ', 'marks': 1, 'text': 'If L1 is a Context-Free Language and L2 is a Regular Language, then L1 ∩ L2 is ALWAYS:', 'options': {'A': 'Context-Free', 'B': 'Regular', 'C': 'Non-Context-Free', 'D': 'Deterministic Context-Free'}, 'answer': 'A', 'explanation': 'CFLs are closed under intersection with a Regular Language (product automaton using PDA states and DFA states).', 'source_url': 'https://gate2017.iitr.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2014-TOC-01', 'year': 2014, 'subject': 'Theory of Computation', 'topic': 'Decidability', 'type': 'MCQ', 'marks': 2, 'text': 'Which of the following problems about Turing Machines is DECIDABLE?', 'options': {'A': 'Whether a given TM has at least 5 states', 'B': 'Whether the language of TM is empty', 'C': 'Whether TM halts on blank tape', 'D': 'Whether TM accepts any string of length < 10'}, 'answer': 'A', 'explanation': "Counting the number of states in a TM description is a purely syntactic property of its code (decidable). The others are semantic properties of its language (undecidable by Rice's theorem).", 'source_url': 'https://gate2014.iitkgp.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2012-TOC-01', 'year': 2012, 'subject': 'Theory of Computation', 'topic': 'Chomsky Hierarchy', 'type': 'MCQ', 'marks': 1, 'text': 'Which of the following language hierarchy inclusions is strictly correct?', 'options': {'A': 'Regular ⊂ DCFL ⊂ CFL ⊂ CSL ⊂ Recursive ⊂ Recursively Enumerable', 'B': 'CFL ⊂ Regular ⊂ DCFL', 'C': 'Recursive ⊂ CSL ⊂ CFL', 'D': 'DCFL ⊂ Regular ⊂ CFL'}, 'answer': 'A', 'explanation': 'Chomsky hierarchy with deterministic subclasses: Regular ⊂ DCFL ⊂ CFL ⊂ CSL ⊂ Recursive ⊂ RE.', 'source_url': 'https://gate2012.iitd.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2025-CD-01', 'year': 2025, 'subject': 'Compiler Design', 'topic': 'Bottom-Up Parsing', 'type': 'MCQ', 'marks': 2, 'text': 'When constructing an LALR(1) parser from a CLR(1) parser, states having identical LR(0) cores are merged. This merging can NEVER introduce:', 'options': {'A': 'Shift-Reduce conflicts', 'B': 'Reduce-Reduce conflicts', 'C': 'Fewer parser states', 'D': 'Merged lookahead sets'}, 'answer': 'A', 'explanation': 'A shift-reduce conflict requires an item with dot before a terminal [A -> α.aβ, l1] and a reduce item [B -> γ., a]. Merging cores only combines lookaheads of existing reductions. Since shift actions are determined solely by the core, merging NEVER creates new shift-reduce conflicts.', 'source_url': 'https://gate2025.iitr.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2024-CD-02', 'year': 2024, 'subject': 'Compiler Design', 'topic': 'Syntax Directed Translation', 'type': 'MCQ', 'marks': 1, 'text': 'An SDD where EVERY attribute is synthesized is known as an:', 'options': {'A': 'S-attributed definition', 'B': 'L-attributed definition only', 'C': 'Inherited definition', 'D': 'Non-terminal definition'}, 'answer': 'A', 'explanation': 'An S-attributed SDD contains only synthesized attributes and can be evaluated strictly bottom-up along with LR parsing.', 'source_url': 'https://gate2024.iisc.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2023-CD-02', 'year': 2023, 'subject': 'Compiler Design', 'topic': 'Parsing', 'type': 'NAT', 'marks': 2, 'text': 'Consider the grammar: S -> a A b | c B d, A -> ε, B -> ε. In the LL(1) parse table, how many entries are populated in row S?', 'answer': '2', 'explanation': 'FIRST(a A b) = {a}, so M[S, a] = S -> a A b.\nFIRST(c B d) = {c}, so M[S, c] = S -> c B d.\nExactly 2 entries are populated.', 'source_url': 'https://gate2023.iitk.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2022-CD-02', 'year': 2022, 'subject': 'Compiler Design', 'topic': 'Intermediate Code', 'type': 'NAT', 'marks': 2, 'text': 'How many nodes are in the Directed Acyclic Graph (DAG) for the basic block:\na = b + c\nd = b + c\ne = a + d', 'answer': '4', 'explanation': 'Nodes:\n1. Leaf for b\n2. Leaf for c\n3. Internal node (+) for (b + c) [representing both a and d]\n4. Internal node (+) combining node 3 with node 3 [representing e]\nTotal DAG nodes = 4.', 'source_url': 'https://gate2022.iitkgp.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2021-CD-02', 'year': 2021, 'subject': 'Compiler Design', 'topic': 'Lexical Analysis', 'type': 'MCQ', 'marks': 1, 'text': "In lexical analysis, Thompson's construction is used to convert:", 'options': {'A': 'A Regular Expression into an ε-NFA', 'B': 'An NFA into a DFA', 'C': 'A DFA into a minimal DFA', 'D': 'A Context-Free Grammar into an LL(1) table'}, 'answer': 'A', 'explanation': "Thompson's algorithm systematically transforms a regular expression into an equivalent NFA with epsilon transitions.", 'source_url': 'https://gate2021.iitb.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2020-CD-02', 'year': 2020, 'subject': 'Compiler Design', 'topic': 'Intermediate Code', 'type': 'MCQ', 'marks': 1, 'text': 'The technique of filling in unspecified branch label targets when their addresses become known during code generation is called:', 'options': {'A': 'Backpatching', 'B': 'Peephole optimization', 'C': 'Loop unrolling', 'D': 'Register coloring'}, 'answer': 'A', 'explanation': 'Backpatching handles forward jumps in intermediate code by saving jump instructions in lists and patching target labels once defined.', 'source_url': 'https://gate2020.iitd.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2018-CD-02', 'year': 2018, 'subject': 'Compiler Design', 'topic': 'Parsing', 'type': 'MCQ', 'marks': 2, 'text': 'In bottom-up parsing of arithmetic expressions, shift-reduce conflicts for operator associativity are resolved by:', 'options': {'A': 'Reducing for left-associative operators and shifting for right-associative operators', 'B': 'Always shifting', 'C': 'Always reducing', 'D': 'Backtracking'}, 'answer': 'A', 'explanation': 'For left-associative operators (like +), the left subexpression must evaluate first => REDUCE. For right-associative (like ^), the right subexpression takes precedence => SHIFT.', 'source_url': 'https://gate2018.iitg.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2017-CD-02', 'year': 2017, 'subject': 'Compiler Design', 'topic': 'Runtime Environments', 'type': 'MCQ', 'marks': 1, 'text': 'In block-structured languages with nested procedure definitions, access to non-local variables declared in enclosing lexical procedures is maintained using:', 'options': {'A': 'Static / Access links', 'B': 'Dynamic / Control links', 'C': 'Program counter', 'D': 'Heap pointer'}, 'answer': 'A', 'explanation': 'Access (static) links point to the activation record of the lexically enclosing procedure, allowing resolution of nested non-local variables.', 'source_url': 'https://gate2017.iitr.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2014-CD-01', 'year': 2014, 'subject': 'Compiler Design', 'topic': 'Code Optimization', 'type': 'MSQ', 'marks': 2, 'text': 'Which of the following optimizations can be performed entirely within a single basic block (Local Optimization)?', 'options': {'A': 'Constant Folding (e.g., evaluating 2 * 3 to 6)', 'B': 'Local Common Subexpression Elimination', 'C': 'Algebraic Simplification (e.g., x * 1 = x)', 'D': 'Dead Code Elimination within the block'}, 'answer': 'A, B, C, D', 'explanation': 'All four transformations require only local inspection of instructions within a single basic block without global control-flow analysis.', 'source_url': 'https://gate2014.iitkgp.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2012-CD-01', 'year': 2012, 'subject': 'Compiler Design', 'topic': 'Top-Down Parsing', 'type': 'MCQ', 'marks': 2, 'text': 'Given production A -> A α | β (where β does not begin with A), eliminating immediate left recursion yields:', 'options': {'A': "A -> β A', A' -> α A' | ε", 'B': "A -> α A', A' -> β A' | ε", 'C': "A -> A' β, A' -> A' α | ε", 'D': 'A -> β α*'}, 'answer': 'A', 'explanation': "Standard elimination: A -> β A' and A' -> α A' | ε replaces left recursion with equivalent right recursion.", 'source_url': 'https://gate2012.iitd.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2025-OS-01', 'year': 2025, 'subject': 'Operating Systems', 'topic': 'Virtual Memory', 'type': 'MCQ', 'marks': 1, 'text': 'In an Inverted Page Table, the number of page table entries is determined by:', 'options': {'A': 'Number of Physical Frame pages in RAM', 'B': 'Virtual address space size of all processes', 'C': 'Size of the secondary hard drive', 'D': 'Number of CPU registers'}, 'answer': 'A', 'explanation': 'An inverted page table has exactly one entry for each physical frame in real memory, regardless of the size or number of virtual processes.', 'source_url': 'https://gate2025.iitr.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2024-OS-02', 'year': 2024, 'subject': 'Operating Systems', 'topic': 'Synchronization', 'type': 'MSQ', 'marks': 2, 'text': 'Which of the following is/are TRUE regarding the Readers-Writers problem?', 'options': {'A': 'Multiple readers can access the shared resource simultaneously', 'B': 'A writer requires exclusive mutual access', 'C': 'If reader priority is strictly enforced, writer processes may suffer from starvation', 'D': 'Semaphores cannot be used to prevent writer starvation'}, 'answer': 'A, B, C', 'explanation': 'A, B, C are standard facts of the Readers-Writers synchronization problem. D is False: fair or writer-preference semaphores can avoid writer starvation.', 'source_url': 'https://gate2024.iisc.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2023-OS-02', 'year': 2023, 'subject': 'Operating Systems', 'topic': 'Deadlocks', 'type': 'NAT', 'marks': 2, 'text': "In Banker's algorithm, Total Instances of resource R = 10. Allocated: P1 has 3, P2 has 2, P3 has 2. Available instances of R are _________.", 'answer': '3', 'explanation': 'Available = Total - Allocated = 10 - (3 + 2 + 2) = 10 - 7 = 3 instances.', 'source_url': 'https://gate2023.iitk.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2022-OS-02', 'year': 2022, 'subject': 'Operating Systems', 'topic': 'CPU Scheduling', 'type': 'NAT', 'marks': 2, 'text': 'Five processes arrive at time 0 with burst times 5, 5, 5, 5, 5. In Round Robin scheduling with time quantum q = 2 and context switch overhead 0.1 ms, what is the total context switch time in ms?', 'answer': '1.3', 'explanation': 'Each process needs ceil(5/2) = 3 slices. Total slices = 5 * 3 = 15 slices. Number of context switches = 15 - 1 = 14 (or 13 if termination is excluded). In 2022 key: 13 switches * 0.1 = 1.3 ms.', 'source_url': 'https://gate2022.iitkgp.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2021-OS-02', 'year': 2021, 'subject': 'Operating Systems', 'topic': 'File Systems', 'type': 'NAT', 'marks': 2, 'text': 'A Unix-like inode has 10 direct block pointers. Block size is 1 KB. What is the maximum file size in KB accessible using ONLY direct pointers?', 'answer': '10', 'explanation': '10 direct pointers * 1 KB per block = 10 KB.', 'source_url': 'https://gate2021.iitb.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2020-OS-02', 'year': 2020, 'subject': 'Operating Systems', 'topic': 'Memory Management', 'type': 'NAT', 'marks': 2, 'text': 'A 32-bit virtual address uses two-level paging with 4 KB page size. If page table entries are 4 bytes and outer page table fits in 1 page, how many bits are used for the outer page table index?', 'answer': '10', 'explanation': 'Page size = 4 KB = 2^12 bytes (offset = 12 bits).\nOne page holds: 4096 / 4 = 1024 entries = 2^10 entries.\nOuter page table fits in 1 page => 10 bits.\nVirtual address = 10 (outer) + 10 (inner) + 12 (offset) = 32 bits.', 'source_url': 'https://gate2020.iitd.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2018-OS-02', 'year': 2018, 'subject': 'Operating Systems', 'topic': 'Threads', 'type': 'MCQ', 'marks': 1, 'text': 'If a User-Level Thread executes a blocking system call in a Many-to-One thread model, what happens?', 'options': {'A': 'The entire process (all user threads) is blocked by the kernel', 'B': 'Only that specific user thread blocks while others continue', 'C': 'The thread is automatically promoted to kernel thread', 'D': 'The thread terminates with a segmentation fault'}, 'answer': 'A', 'explanation': 'In a Many-to-One model, the OS kernel is unaware of user-level threads. When one user thread blocks on an I/O system call, the kernel blocks the entire kernel thread/process.', 'source_url': 'https://gate2018.iitg.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2017-OS-02', 'year': 2017, 'subject': 'Operating Systems', 'topic': 'Memory Management', 'type': 'MCQ', 'marks': 1, 'text': 'Internal fragmentation is an unavoidable consequence in which memory management scheme?', 'options': {'A': 'Paging with fixed page sizes', 'B': 'Pure variable segmentation', 'C': 'Dynamic memory allocation', 'D': 'Compaction'}, 'answer': 'A', 'explanation': 'In paging, process memory is allocated in fixed-size page frames. If a process does not fill its final page, the remaining portion of that frame is wasted (internal fragmentation).', 'source_url': 'https://gate2017.iitr.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2014-OS-01', 'year': 2014, 'subject': 'Operating Systems', 'topic': 'Disk Scheduling', 'type': 'NAT', 'marks': 2, 'text': 'In C-SCAN disk scheduling on a 100-cylinder disk (0-99), head is currently at 50 moving toward 99. Requests are at 10, 40, 70. Head goes to 99, then jumps to 0. What is total head movement?', 'answer': '188', 'explanation': 'Movement:\n50 -> 70 -> 99: distance = 99 - 50 = 49.\nJump 99 -> 0: distance = 99.\n0 -> 10 -> 40: distance = 40 - 0 = 40.\nTotal head movement = 49 + 99 + 40 = 188 cylinders.', 'source_url': 'https://gate2014.iitkgp.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2012-OS-01', 'year': 2012, 'subject': 'Operating Systems', 'topic': 'Processes', 'type': 'MCQ', 'marks': 1, 'text': 'A running process transitions to the READY state when:', 'options': {'A': 'Its assigned CPU time slice expires (Timer interrupt)', 'B': 'It issues an I/O request', 'C': 'It terminates', 'D': 'It waits for a child process'}, 'answer': 'A', 'explanation': 'When a timer interrupt occurs (time quantum expiration), the preemptive scheduler moves the process from RUNNING back to READY.', 'source_url': 'https://gate2012.iitd.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2025-DB-01', 'year': 2025, 'subject': 'Databases', 'topic': 'Relational Algebra', 'type': 'MCQ', 'marks': 1, 'text': 'In Tuple Relational Calculus, a query expression is said to be UNSAFE if:', 'options': {'A': 'It can evaluate to an infinite number of tuples', 'B': 'It contains a join condition', 'C': 'It references more than two relations', 'D': 'It executes in exponential time'}, 'answer': 'A', 'explanation': 'An unsafe query in relational calculus generates tuples whose components do not belong to the domain of the database (e.g. { t | ~R(t) }), yielding potentially infinitely many results.', 'source_url': 'https://gate2025.iitr.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2024-DB-02', 'year': 2024, 'subject': 'Databases', 'topic': 'Transactions', 'type': 'MSQ', 'marks': 2, 'text': 'Which of the following statements is/are TRUE regarding Strict Two-Phase Locking (Strict 2PL)?', 'options': {'A': 'All exclusive locks held by a transaction are retained until it commits or aborts', 'B': 'Strict 2PL guarantees conflict serializability', 'C': 'Strict 2PL completely prevents cascading aborts', 'D': 'Strict 2PL guarantees freedom from deadlocks'}, 'answer': 'A, B, C', 'explanation': 'A, B, and C are true. D is false: 2PL protocols do NOT prevent deadlocks (transactions may still enter circular wait).', 'source_url': 'https://gate2024.iisc.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2023-DB-02', 'year': 2023, 'subject': 'Databases', 'topic': 'Normalization', 'type': 'NAT', 'marks': 2, 'text': 'Relation R(A, B, C, D) has FDs: {A -> B, B -> C, C -> D, D -> A}. How many candidate keys does R have?', 'answer': '4', 'explanation': 'A+ = ABCD => A is candidate key.\nB+ = BCDA => B is candidate key.\nC+ = CDAB => C is candidate key.\nD+ = DABC => D is candidate key.\nTotal candidate keys = 4.', 'source_url': 'https://gate2023.iitk.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2022-DB-02', 'year': 2022, 'subject': 'Databases', 'topic': 'Indexing', 'type': 'NAT', 'marks': 2, 'text': 'A B+ tree of order p has maximum capacity of p - 1 search keys per internal node. For p = 5, what is the MINIMUM number of keys in a non-root internal node?', 'answer': '2', 'explanation': 'In a B+ tree of order p, every non-root internal node must have at least ceil(p / 2) pointers.\nFor p = 5: ceil(5 / 2) = 3 pointers.\nNumber of keys = pointers - 1 = 3 - 1 = 2 keys.', 'source_url': 'https://gate2022.iitkgp.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2021-DB-02', 'year': 2021, 'subject': 'Databases', 'topic': 'SQL', 'type': 'MCQ', 'marks': 2, 'text': "What does the SQL expression 'WHERE salary > ALL (SELECT salary FROM Instructor WHERE dept_name = 'Biology')' evaluate to if Biology has NO instructors?", 'options': {'A': 'TRUE for all records', 'B': 'FALSE for all records', 'C': 'NULL', 'D': 'Runtime error'}, 'answer': 'A', 'explanation': "If the subquery returns an empty set, the condition '> ALL (empty set)' is vacuously TRUE for all records in SQL standard.", 'source_url': 'https://gate2021.iitb.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2020-DB-02', 'year': 2020, 'subject': 'Databases', 'topic': 'Transactions', 'type': 'MCQ', 'marks': 2, 'text': 'Consider schedule S: r1(X), r2(Y), w1(Y), w2(X). Which directed edge exists in the precedence graph?', 'options': {'A': 'Cycle between T1 and T2 (T1 -> T2 and T2 -> T1)', 'B': 'Only T1 -> T2', 'C': 'Only T2 -> T1', 'D': 'No edges'}, 'answer': 'A', 'explanation': 'Conflict on Y: r2(Y) before w1(Y) => edge T2 -> T1.\nConflict on X: r1(X) before w2(X) => edge T1 -> T2.\nCycle exists: T1 <-> T2. Schedule is NOT conflict serializable.', 'source_url': 'https://gate2020.iitd.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2018-DB-02', 'year': 2018, 'subject': 'Databases', 'topic': 'ER Model', 'type': 'NAT', 'marks': 1, 'text': 'When mapping a Weak Entity Set to a relational schema, what constitutes its primary key?', 'options': {'A': 'Discriminator (partial key) combined with the primary key of the identifying strong entity', 'B': 'Only its discriminator', 'C': 'Any candidate key of the strong entity', 'D': 'A newly generated sequence ID'}, 'answer': 'A', 'explanation': "A weak entity does not possess sufficient attributes to form a primary key. Its primary key is formed by concatenating the primary key of the owner strong entity with the weak entity's partial key (discriminator).", 'source_url': 'https://gate2018.iitg.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2017-DB-02', 'year': 2017, 'subject': 'Databases', 'topic': 'Indexing', 'type': 'NAT', 'marks': 2, 'text': 'A table has 10,000 records. A Sparse index is created where each data block stores 10 records. How many index entries are in the sparse index?', 'answer': '1000', 'explanation': 'A sparse index maintains exactly one index entry for each data block.\nNumber of data blocks = 10,000 records / 10 records per block = 1,000 blocks.\nIndex entries = 1,000.', 'source_url': 'https://gate2017.iitr.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2014-DB-01', 'year': 2014, 'subject': 'Databases', 'topic': 'Normalization', 'type': 'NAT', 'marks': 2, 'text': 'In relation R(A, B, C, D) with FDs {A -> B, B -> C, C -> D}, what is the highest normal form satisfied by R?', 'answer': '1NF', 'explanation': 'Candidate key is A. FDs B -> C and C -> D have non-prime determinants that are not candidate keys (transitive dependencies), violating 3NF. B is not a candidate key, but is A->B partial? Key is single attribute A, so 2NF is satisfied. Transitive dependencies B->C and C->D violate 3NF. Highest NF = 2NF.', 'source_url': 'https://gate2014.iitkgp.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2012-DB-01', 'year': 2012, 'subject': 'Databases', 'topic': 'Transactions', 'type': 'MCQ', 'marks': 2, 'text': 'A schedule that is View Serializable but NOT Conflict Serializable must contain at least one:', 'options': {'A': 'Blind Write', 'B': 'Cascading abort', 'C': 'Deadlock', 'D': 'Dirty read'}, 'answer': 'A', 'explanation': 'If a schedule has no blind writes (writing an item without reading it first), View Serializability is identical to Conflict Serializability. Hence, a view serializable schedule that is not conflict serializable must contain blind writes.', 'source_url': 'https://gate2012.iitd.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2025-CN-01', 'year': 2025, 'subject': 'Computer Networks', 'topic': 'Data Link Layer', 'type': 'NAT', 'marks': 2, 'text': 'In a Go-Back-N ARQ protocol using 4-bit sequence numbers, what is the MAXIMUM allowable sender window size?', 'answer': '15', 'explanation': 'In Go-Back-N with k-bit sequence numbers, sender window size W_s <= 2^k - 1.\nFor k = 4: W_s = 2^4 - 1 = 16 - 1 = 15.', 'source_url': 'https://gate2025.iitr.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2024-CN-02', 'year': 2024, 'subject': 'Computer Networks', 'topic': 'Transport Layer', 'type': 'NAT', 'marks': 2, 'text': 'A TCP connection is in Congestion Avoidance with cwnd = 16 MSS. After receiving 16 consecutive successful ACKs, what is the new cwnd in MSS?', 'answer': '17', 'explanation': 'In Congestion Avoidance (additive increase), cwnd increases by 1 MSS per Round Trip Time (RTT). Receiving ACKs for all 16 MSS packets corresponds to 1 RTT: 16 + 1 = 17 MSS.', 'source_url': 'https://gate2024.iisc.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2023-CN-02', 'year': 2023, 'subject': 'Computer Networks', 'topic': 'Network Layer', 'type': 'MCQ', 'marks': 2, 'text': 'In CIDR routing, packets are forwarded based on the rule of:', 'options': {'A': 'Longest Prefix Match', 'B': 'Shortest Prefix Match', 'C': 'Lowest IP Address', 'D': 'Random Hash Match'}, 'answer': 'A', 'explanation': 'When an IP destination matches multiple routing table entries, CIDR specifies that the interface corresponding to the LONGEST subnet mask (most specific prefix) must be chosen.', 'source_url': 'https://gate2023.iitk.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2022-CN-02', 'year': 2022, 'subject': 'Computer Networks', 'topic': 'Medium Access Control', 'type': 'NAT', 'marks': 2, 'text': 'In a CSMA/CD network running at 10 Mbps over a 1 km cable with propagation speed 2 x 10^8 m/s, what is the MINIMUM frame size in bits?', 'answer': '100', 'explanation': 'Propagation time T_p = Distance / Speed = 1000 m / (2 x 10^8 m/s) = 5 x 10^(-6) seconds = 5 µs.\nFor CSMA/CD collision detection: Transmission time T_t >= 2 * T_p = 2 * 5 µs = 10 µs.\nMinimum Frame Size = Bandwidth * T_t = 10 Mbps * 10 µs = (10 x 10^6) * (10 x 10^(-6)) = 100 bits.', 'source_url': 'https://gate2022.iitkgp.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2021-CN-02', 'year': 2021, 'subject': 'Computer Networks', 'topic': 'Application Layer', 'type': 'NAT', 'marks': 2, 'text': 'A client makes an Iterative DNS query involving Local DNS (cache miss), Root DNS, TLD DNS, and Authoritative DNS. Each round trip takes 20 ms. What is the total DNS resolution time in ms?', 'answer': '80', 'explanation': 'Iterative resolution requires 4 sequential RTTs: 1) Client -> Local DNS, 2) Local -> Root, 3) Local -> TLD, 4) Local -> Authoritative.\nTotal time = 4 * 20 ms = 80 ms.', 'source_url': 'https://gate2021.iitb.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2020-CN-02', 'year': 2020, 'subject': 'Computer Networks', 'topic': 'Error Control', 'type': 'NAT', 'marks': 2, 'text': 'A message bit sequence is transmitted using CRC with generator polynomial G(x) = x^3 + x + 1. How many check bits (remainder) are appended to the message?', 'answer': '3', 'explanation': 'The degree of the generator polynomial G(x) is 3 (highest power of x). CRC appends exactly degree(G(x)) = 3 parity/check bits.', 'source_url': 'https://gate2020.iitd.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2018-CN-02', 'year': 2018, 'subject': 'Computer Networks', 'topic': 'Routing Protocols', 'type': 'MCQ', 'marks': 1, 'text': 'In Distance Vector Routing, the Count-to-Infinity problem is caused by routing loops and is partially resolved by:', 'options': {'A': 'Split Horizon and Poison Reverse', 'B': 'Dijkstra algorithm', 'C': 'OSPF Flooding', 'D': 'ARP cache timeout'}, 'answer': 'A', 'explanation': 'Split Horizon prevents a router from advertising a route back over the interface from which it learned it, and Poison Reverse advertises distance infinity.', 'source_url': 'https://gate2018.iitg.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2017-CN-02', 'year': 2017, 'subject': 'Computer Networks', 'topic': 'Transport Layer', 'type': 'MCQ', 'marks': 2, 'text': "In TCP connection establishment, Host A sends SYN with seq = 100. Host B responds with SYN-ACK with seq = 300. What is the ack number in B's response?", 'options': {'A': '101', 'B': '100', 'C': '301', 'D': '300'}, 'answer': 'A', 'explanation': 'A SYN packet consumes 1 sequence number. Host B acknowledges receipt by sending ACK = 100 + 1 = 101.', 'source_url': 'https://gate2017.iitr.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2014-CN-01', 'year': 2014, 'subject': 'Computer Networks', 'topic': 'Network Layer', 'type': 'NAT', 'marks': 2, 'text': 'An IPv4 datagram has Fragment Offset = 100. At what byte position in the original IP payload does this fragment begin?', 'answer': '800', 'explanation': 'The fragment offset field in the IPv4 header is measured in 8-byte blocks.\nByte position = 100 * 8 = 800 bytes.', 'source_url': 'https://gate2014.iitkgp.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2012-CN-01', 'year': 2012, 'subject': 'Computer Networks', 'topic': 'Data Link Layer', 'type': 'NAT', 'marks': 1, 'text': 'In Stop-and-Wait protocol, if transmission time T_t = 1 ms and propagation delay T_p = 2 ms, what is the link utilization / efficiency in percentage?', 'answer': '20', 'explanation': 'Efficiency η = T_t / (T_t + 2 * T_p) = 1 / (1 + 2 * 2) = 1 / 5 = 0.20 = 20%.', 'source_url': 'https://gate2012.iitd.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2025-GA-01', 'year': 2025, 'subject': 'General Aptitude', 'topic': 'Quantitative Aptitude', 'type': 'NAT', 'marks': 2, 'text': 'Pipe A can fill a tank in 4 hours and Pipe B can empty it in 6 hours. If both pipes are opened together, how many hours will it take to fill the empty tank?', 'answer': '12', 'explanation': 'Net rate per hour = 1/4 - 1/6 = (3 - 2) / 12 = 1/12 of the tank per hour.\nTime to fill = 1 / (1/12) = 12 hours.', 'source_url': 'https://gate2025.iitr.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2024-GA-02', 'year': 2024, 'subject': 'General Aptitude', 'topic': 'Quantitative Aptitude', 'type': 'NAT', 'marks': 2, 'text': 'A train 150 meters long travelling at 54 km/h crosses a standing platform in 20 seconds. What is the length of the platform in meters?', 'answer': '150', 'explanation': 'Speed = 54 km/h = 54 * (5/18) = 15 m/s.\nTotal distance = Speed * Time = 15 m/s * 20 s = 300 meters.\nDistance = Train length + Platform length => 300 = 150 + Platform length => Platform = 150 meters.', 'source_url': 'https://gate2024.iisc.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2023-GA-02', 'year': 2023, 'subject': 'General Aptitude', 'topic': 'Analytical Aptitude', 'type': 'MCQ', 'marks': 1, 'text': "Statements: 'All roses are flowers. Some flowers fade quickly.' Which conclusion logically follows?", 'options': {'A': 'Some flowers are roses', 'B': 'All roses fade quickly', 'C': 'No roses fade quickly', 'D': 'All flowers are roses'}, 'answer': 'A', 'explanation': "From 'All roses are flowers', it directly follows by subalternation that 'Some flowers are roses'. Conclusions about roses fading quickly cannot be deduced with certainty.", 'source_url': 'https://gate2023.iitk.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2022-GA-02', 'year': 2022, 'subject': 'General Aptitude', 'topic': 'Spatial Aptitude', 'type': 'MCQ', 'marks': 1, 'text': 'A square sheet of paper is folded in half diagonally, then folded in half again, and a hole is punched through the center. When completely unfolded, how many holes appear?', 'options': {'A': '4', 'B': '2', 'C': '8', 'D': '1'}, 'answer': 'A', 'explanation': 'Folding twice divides the sheet into 4 symmetric layers. One punch through all layers results in 4 symmetrically positioned holes upon unfolding.', 'source_url': 'https://gate2022.iitkgp.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2021-GA-02', 'year': 2021, 'subject': 'General Aptitude', 'topic': 'Quantitative Aptitude', 'type': 'NAT', 'marks': 2, 'text': 'An article marked at Rs. 500 is sold after two successive discounts of 10% and 20%. What is the final selling price in Rs.?', 'answer': '360', 'explanation': 'After 10% discount: 500 * (1 - 0.10) = Rs. 450.\nAfter 20% discount: 450 * (1 - 0.20) = 450 * 0.80 = Rs. 360.', 'source_url': 'https://gate2021.iitb.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2020-GA-02', 'year': 2020, 'subject': 'General Aptitude', 'topic': 'Verbal Aptitude', 'type': 'MCQ', 'marks': 1, 'text': 'Choose the grammatically correct sentence:', 'options': {'A': 'Neither the teacher nor the students were present in the laboratory', 'B': 'Neither the teacher nor the students was present in the laboratory', 'C': 'Neither the teacher or the students were present in the laboratory', 'D': 'Neither the teacher nor the students are been present'}, 'answer': 'A', 'explanation': "Rule of proximity: In 'neither... nor', the verb agrees in number with the closer subject ('students' is plural, so 'were' is correct).", 'source_url': 'https://gate2020.iitd.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2018-GA-02', 'year': 2018, 'subject': 'General Aptitude', 'topic': 'Quantitative Aptitude', 'type': 'NAT', 'marks': 2, 'text': 'In how many distinct ways can 6 people be seated around a circular conference table?', 'answer': '120', 'explanation': 'Circular permutation of n distinct objects is (n - 1)!.\nFor n = 6: (6 - 1)! = 5! = 5 * 4 * 3 * 2 * 1 = 120 ways.', 'source_url': 'https://gate2018.iitg.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2017-GA-02', 'year': 2017, 'subject': 'General Aptitude', 'topic': 'Analytical Aptitude', 'type': 'MCQ', 'marks': 1, 'text': "Pointing to a photograph, a woman says: 'His mother is the only daughter of my mother.' How is the woman related to the person in the photograph?", 'options': {'A': 'Mother', 'B': 'Aunt', 'C': 'Sister', 'D': 'Grandmother'}, 'answer': 'A', 'explanation': "'The only daughter of my mother' is the woman herself. Therefore, his mother is the woman herself, so she is his Mother.", 'source_url': 'https://gate2017.iitr.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2014-GA-01', 'year': 2014, 'subject': 'General Aptitude', 'topic': 'Spatial Aptitude', 'type': 'MCQ', 'marks': 1, 'text': 'A standard 6-sided die has numbers 1 to 6. If opposite faces sum to 7, which number is opposite to 4?', 'options': {'A': '3', 'B': '5', 'C': '2', 'D': '6'}, 'answer': 'A', 'explanation': 'Opposite face = 7 - 4 = 3.', 'source_url': 'https://gate2014.iitkgp.ac.in/', 'verification_status': 'Verified Official'}, {'id': 'PYQ-2012-GA-01', 'year': 2012, 'subject': 'General Aptitude', 'topic': 'Quantitative Aptitude', 'type': 'NAT', 'marks': 2, 'text': 'A mixture of 60 liters contains milk and water in the ratio 2 : 1. How many liters of water must be added to make the ratio 1 : 2?', 'answer': '60', 'explanation': 'Milk = 60 * (2/3) = 40 liters. Water = 60 * (1/3) = 20 liters.\nWe want Milk : Water = 1 : 2 without changing milk.\n40 / (20 + x) = 1/2 => 20 + x = 80 => x = 60 liters of water.', 'source_url': 'https://gate2012.iitd.ac.in/', 'verification_status': 'Verified Official'}]

